def _fuso_usuario():
    """Retorna o fuso IANA do navegador, com fallback configurável."""
    nome_fuso = None
    try:
        nome_fuso = st.session_state.get("_timezone_navegador")
    except Exception:
        nome_fuso = None
    if not nome_fuso:
        try:
            nome_fuso = st.query_params.get("_tz_browser")
        except Exception:
            nome_fuso = None
    try:
        nome_fuso = nome_fuso or getattr(st.context, "timezone", None)
    except Exception:
        pass
    if not nome_fuso:
        nome_fuso = st.secrets.get("USER_TIMEZONE_DEFAULT", "America/Sao_Paulo")
    try:
        return ZoneInfo(str(nome_fuso))
    except Exception:
        return ZoneInfo("America/Sao_Paulo")

def _agora_usuario():
    """Horário local usado em caches, coletas e análises visíveis ao usuário."""
    return datetime.datetime.now(_fuso_usuario())

def _limitar_threads_cpu_ocr_apos_import():
    try:
        import torch
        torch.set_num_threads(1)
        try:
            torch.set_num_interop_threads(1)
        except RuntimeError:
            pass
    except Exception as e:
        print(f"[OCR-DEBUG] não consegui limitar threads do torch: {e!r}", flush=True)
    try:
        import cv2
        cv2.setNumThreads(1)
    except Exception as e:
        print(f"[OCR-DEBUG] não consegui limitar threads do cv2: {e!r}", flush=True)

def _rss_startup_sem_torch_mb():
    try:
        with open("/proc/self/status", "r", encoding="utf-8") as _f:
            for _linha in _f:
                if _linha.startswith("VmRSS:"):
                    return float(_linha.split()[1]) / 1024.0
    except Exception:
        pass
    return 0.0

print(
    f"[MEM-DEBUG] startup sem import antecipado de torch: "
    f"RSS={_rss_startup_sem_torch_mb():.1f} MB",
    flush=True,
)


