# O servidor pode estar em UTC ou em outra região. Captura uma única vez o
# fuso IANA real do navegador e o mantém na sessão para todos os registros
# visíveis de coleta, cache e análise.
try:
    _tz_query = st.query_params.get("_tz_browser")
    if _tz_query:
        try:
            ZoneInfo(str(_tz_query))
            st.session_state["_timezone_navegador"] = str(_tz_query)
        except Exception:
            pass
        try:
            del st.query_params["_tz_browser"]
        except Exception:
            pass
except Exception:
    _tz_query = None

if not st.session_state.get("_timezone_navegador"):
    components.html("""
    <script>
    (function () {
        try {
            var tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
            if (!tz) return;
            var url = new URL(window.parent.location.href);
            if (url.searchParams.get('_tz_browser') === tz) return;
            url.searchParams.set('_tz_browser', tz);
            window.parent.location.replace(url.toString());
        } catch (e) {}
    })();
    </script>
    """, height=0, scrolling=False)

_MAX_CPU_PESADA = int(st.secrets.get("MAX_CPU_PESADA_CONCORRENTE", 1))
_MAX_DOWNLOADS_MIDIA = int(st.secrets.get("MAX_DOWNLOADS_MIDIA_CONCORRENTES", 1))
_MAX_API_IO = int(st.secrets.get("MAX_API_IO_CONCORRENTE", 5))

_semaforo_cpu_pesada = threading.BoundedSemaphore(max(1, _MAX_CPU_PESADA))
_semaforo_api_io = threading.BoundedSemaphore(max(1, _MAX_API_IO))

@contextmanager
def _recurso_cpu_pesada(nome: str):
    """Serializa tarefas pesadas locais (OCR/ffmpeg/Whisper).

    O nome é só para debug. O semáforo é global ao processo, então um OCR
    não roda ao mesmo tempo que uma compressão de vídeo/thumbnail/Whisper.
    """
    _semaforo_cpu_pesada.acquire()
    try:
        yield
    finally:
        _semaforo_cpu_pesada.release()

@contextmanager
def _recurso_api_io():
    """Limita rajadas de I/O remoto sem transformar tudo em sequencial."""
    _semaforo_api_io.acquire()
    try:
        yield
    finally:
        _semaforo_api_io.release()


_http_local = threading.local()

def _http_session() -> requests.Session:
    sess = getattr(_http_local, "session", None)
    if sess is None:
        sess = requests.Session()
        try:
            from requests.adapters import HTTPAdapter
            adapter = HTTPAdapter(pool_connections=8, pool_maxsize=8, max_retries=0)
            sess.mount("https://", adapter)
            sess.mount("http://", adapter)
        except Exception:
            pass
        _http_local.session = sess
    return sess

def _http_get(*args, **kwargs):
    return _http_session().get(*args, **kwargs)

def _http_post(*args, **kwargs):
    return _http_session().post(*args, **kwargs)

def _http_head(*args, **kwargs):
    return _http_session().head(*args, **kwargs)


def _ads_empresa_tem_dados(cache: dict, nome_empresa: str) -> bool:
    entry = (cache or {}).get(nome_empresa) or {}
    return bool(entry.get("data"))

def _ads_empresas_com_dados(todas_empresas: list, cache: dict) -> list:
    return [e for e in (todas_empresas or []) if _ads_empresa_tem_dados(cache, e.get("nome", ""))]

def _ads_resolver_empresa_ativa(todas_empresas: list, cache: dict, ativa: str):
    """Mantém uma empresa ativa somente se ela realmente tiver dados."""
    com_dados = _ads_empresas_com_dados(todas_empresas, cache)
    if ativa == "__comparativo__":
        return ativa, com_dados
    if any(e.get("nome") == ativa for e in com_dados):
        return ativa, com_dados
    return (com_dados[0]["nome"] if com_dados else ""), com_dados

_playwright_install_lock = threading.Lock()
_playwright_install_status = [None]  # None=não tentou; True/False=resultado nesta instância

def _garantir_chromium_playwright() -> bool:
    """Garante Chromium de forma LAZY, só quando o fallback realmente precisar.

    V31: o app não baixa mais ~115 MB de Chromium em todo startup/deploy.
    O estado fica em cache Python puro, inclusive quando chamado por background thread.
    """
    if _playwright_install_status[0] is not None:
        return bool(_playwright_install_status[0])
    with _playwright_install_lock:
        if _playwright_install_status[0] is not None:
            return bool(_playwright_install_status[0])
        try:
            r = subprocess.run(
                [sys.executable, "-m", "playwright", "install", "chromium"],
                check=True, capture_output=True, timeout=300, text=True,
            )
            print(f"[PLAYWRIGHT] chromium instalado sob demanda. stdout: {r.stdout[-500:]}", flush=True)
            _playwright_install_status[0] = True
        except Exception as e:
            stderr = getattr(e, "stderr", "")
            print(f"[PLAYWRIGHT] FALHA ao instalar chromium sob demanda: {e!r} | stderr: {stderr}", flush=True)
            _playwright_install_status[0] = False
        return bool(_playwright_install_status[0])


