AVATAR_COLORS = ["#27ae60", "#3a9fd6", "#2ecc71", "#5bc4f5", "#1a7abf", "#1a2e4a"]

def get_avatar_color(index: int) -> str:
    return AVATAR_COLORS[index % len(AVATAR_COLORS)]

def get_minha_empresa_color() -> str:
    return AVATAR_COLORS[0]

def get_concorrente_color(concorrente_index: int) -> str:
    return AVATAR_COLORS[(concorrente_index + 1) % len(AVATAR_COLORS)]


def remover_acentos(texto):
    return ''.join(
        c for c in unicodedata.normalize('NFD', texto)
        if unicodedata.category(c) != 'Mn'
    )

def limpar_site(url):
    if not url:
        return ""
    url = url.strip().lower()
    url = re.sub(r"^https?:\/\/", "", url, flags=re.IGNORECASE)
    url = re.sub(r"^www\.", "", url, flags=re.IGNORECASE)
    url = remover_acentos(url)
    url = re.sub(r"[^a-z0-9\.\-\/]", "", url)
    url = url.rstrip("/")
    return url

def gerar_avatar(nome):
    nome = nome.strip().upper()
    if not nome:
        return "?"
    partes = nome.split()
    if len(partes) == 1:
        return partes[0][0]
    return partes[0][0] + partes[1][0]

def obter_instagram_handle(valor):
    if not valor:
        return ""
    valor = valor.strip()
    valor = re.sub(r"^https?:\/\/(www\.)?instagram\.com\/", "", valor, flags=re.IGNORECASE)
    valor = valor.strip("/")
    valor = valor.lstrip("@")
    if valor:
        valor = "@" + valor
    return valor

def obter_facebook_handle(valor):
    if not valor:
        return ""
    valor = valor.strip()
    valor = re.sub(r"^https?:\/\/(www\.)?facebook\.com\/", "", valor, flags=re.IGNORECASE)
    valor = valor.strip("/")
    return valor

def empresa_tem_dados(emp):
    return bool(emp.get("nome", "").strip())

def formatar_url(url):
    if not url:
        return ""
    url = url.strip()
    if not url.startswith("http"):
        url = "https://" + url
    return url


def login_supabase(email: str, senha: str):
    def _mensagem_login(exc) -> str:
        texto = str(exc or "")
        baixo = texto.lower()
        if _erro_supabase_transitorio(exc):
            return (
                "O serviço de acesso está temporariamente indisponível. "
                "Aguarde alguns instantes e tente novamente."
            )
        if "invalid login credentials" in baixo or "invalid credentials" in baixo:
            return "E-mail ou senha incorretos."
        if "email not confirmed" in baixo:
            return "Confirme seu e-mail antes de entrar na plataforma."
        if "user not found" in baixo:
            return "E-mail ou senha incorretos."
        return "Não foi possível entrar agora. Tente novamente em instantes."

    def _recriar_cliente_auth():
        """Descarta somente a conexao HTTP que falhou e cria outra limpa."""
        global supabase
        st.session_state.pop("_supabase_client", None)
        supabase = get_supabase()

    def _descricao_segura(exc) -> str:
        """Detalha o erro no log sem registrar e-mail, senha ou URL do projeto."""
        mensagem = str(exc or "").strip().replace("\n", " ")
        mensagem = re.sub(r"https?://\\S+", "[URL ocultada]", mensagem)
        return f"{type(exc).__name__}: {mensagem[:500]}"

    _ultimo_erro = None
    for _tentativa in range(3):
        print(
            f"[AUTH-V222] iniciando tentativa={_tentativa + 1}/3",
            flush=True,
        )
        try:
            res = supabase.auth.sign_in_with_password({"email": email, "password": senha})
            if res.user:
                garantir_linha_usuario(res.user.id)
                print(
                    f"[AUTH-V222] login concluido tentativa={_tentativa + 1}/3",
                    flush=True,
                )
            return res.user, None
        except (httpx.TimeoutException, httpx.ConnectError, httpx.ReadTimeout) as e:
            _ultimo_erro = e
            print(
                f"[AUTH-V222] falha de rede tentativa={_tentativa + 1}/3: {_descricao_segura(e)}",
                flush=True,
            )
            if _tentativa < 2:
                try:
                    _recriar_cliente_auth()
                    print("[AUTH-V222] conexao de autenticacao recriada", flush=True)
                except Exception as erro_reconexao:
                    _ultimo_erro = erro_reconexao
                    print(
                        f"[AUTH-V222] erro ao recriar conexao: {_descricao_segura(erro_reconexao)}",
                        flush=True,
                    )
                time.sleep(1 + _tentativa)
                continue
        except Exception as e:
            if _erro_supabase_transitorio(e):
                _ultimo_erro = e
                print(
                    f"[AUTH-V222] gateway indisponivel tentativa={_tentativa + 1}/3: {_descricao_segura(e)}",
                    flush=True,
                )
                if _tentativa < 2:
                    try:
                        _recriar_cliente_auth()
                        print("[AUTH-V222] conexao de autenticacao recriada", flush=True)
                    except Exception as erro_reconexao:
                        _ultimo_erro = erro_reconexao
                        print(
                            f"[AUTH-V222] erro ao recriar conexao: {_descricao_segura(erro_reconexao)}",
                            flush=True,
                        )
                    time.sleep(1 + _tentativa)
                    continue
            print(
                f"[AUTH-V222] falha definitiva tentativa={_tentativa + 1}/3: {_descricao_segura(e)}",
                flush=True,
            )
            return None, _mensagem_login(e)
    print(
        f"[AUTH-V222] tentativas esgotadas: {_descricao_segura(_ultimo_erro)}",
        flush=True,
    )
    return None, _mensagem_login(_ultimo_erro)

def enviar_recuperacao_senha(email: str):
    """Solicita ao Supabase o e-mail de redefinição de senha.

    A mensagem exibida ao usuário é sempre neutra para não revelar se um
    endereço está ou não cadastrado na plataforma.
    """
    try:
        supabase.auth.reset_password_for_email(email.strip())
        return True, None
    except Exception as e:
        if _erro_supabase_transitorio(e):
            return False, (
                "O serviço de recuperação está temporariamente indisponível. "
                "Tente novamente em alguns instantes."
            )
        return False, "Não foi possível enviar o e-mail de recuperação agora. Tente novamente."

def reenviar_confirmacao_email(email: str):
    """Reenvia o e-mail de confirmação de cadastro pelo Supabase."""
    try:
        supabase.auth.resend({"type": "signup", "email": email.strip()})
        return True, None
    except Exception as e:
        if _erro_supabase_transitorio(e):
            return False, (
                "O serviço de confirmação está temporariamente indisponível. "
                "Tente novamente em alguns instantes."
            )
        return False, "Não foi possível reenviar a confirmação agora. Tente novamente."

def cadastro_supabase(email: str, senha: str, nome: str = ""):
    try:
        payload = {"email": email, "password": senha}
        if nome.strip():
            payload["options"] = {"data": {"full_name": nome.strip()}}
        res = supabase.auth.sign_up(payload)
        if res.user and res.session:
            garantir_linha_usuario(res.user.id)
        return res.user, None
    except Exception as e:
        return None, str(e)

def _html(bloco: str) -> str:
    """Remove a indentação de cada linha antes de mandar pro st.markdown.
    Sem isso, HTML com 4+ espaços de indentação (comum em f-strings
    dentro de loops/with aninhados) é interpretado pelo parser de
    Markdown como bloco de código, e aparece como texto cru na tela."""
    return "\n".join(l.strip() for l in bloco.strip().split("\n"))

def obter_nome_usuario() -> str:
    """Nome de exibição do usuário logado. Cai pro prefixo do e-mail
    se ele ainda não tiver preenchido o nome."""
    u = st.session_state.get("user")
    if not u:
        return ""
    nome = (getattr(u, "user_metadata", None) or {}).get("full_name", "").strip()
    if nome:
        return nome
    return (u.email or "").split("@")[0]

def atualizar_nome_usuario(novo_nome: str) -> bool:
    """Atualiza o nome nos metadados do usuário no Supabase Auth."""
    try:
        res = supabase.auth.update_user({"data": {"full_name": novo_nome.strip()}})
        if res.user:
            st.session_state.user = res.user
        return True
    except Exception as e:
        st.toast(f"Erro ao atualizar nome: {e}", icon="⚠️")
        return False

def atualizar_senha_usuario(nova_senha: str) -> bool:
    """Atualiza a senha do usuário logado no Supabase Auth."""
    try:
        supabase.auth.update_user({"password": nova_senha})
        return True
    except Exception as e:
        st.toast(f"Erro ao atualizar senha: {e}", icon="⚠️")
        return False

def garantir_linha_usuario(user_id: str):
    try:
        existe = (
            supabase.table("ci_dados")
            .select("user_id")
            .eq("user_id", user_id)
            .execute()
        )
        if not existe.data:
            supabase.table("ci_dados").insert({
                "user_id": user_id,
                "minha_empresa": {},
                "concorrentes": [],
                "metricas_redes": {},
                "ads_cache": {},
                "analises_salvas": [],
                "redes_analises_salvas": [],
                "ads_analises_salvas": [],
                "seo_cache": {},
            }).execute()
    except Exception as e:
        st.toast(f"Erro ao inicializar dados: {e}", icon="⚠️")

def logout_supabase():
    try:
        supabase.auth.sign_out()
    except Exception:
        pass
    st.session_state["_auth_cookie_action"] = {"acao": "remover"}


def carregar_dados_usuario(user_id: str) -> dict:
    try:
        _colunas_login = (
            "minha_empresa,concorrentes,metricas_redes,ads_cache,"
            "analises_salvas,redes_analises_salvas,ads_analises_salvas,seo_cache"
        )
        res = (
            supabase.table("ci_dados")
            .select(_colunas_login)
            .eq("user_id", user_id)
            .limit(1)
            .execute()
        )
        if res.data:
            row = res.data[0]
            for _col_blob_v291, _padrao_blob_v291 in (
                ("metricas_redes", {}), ("ads_cache", {}),
                ("analises_salvas", []), ("redes_analises_salvas", []),
                ("ads_analises_salvas", []), ("seo_cache", {}),
            ):
                _cache_blob_ci_v291(
                    user_id, _col_blob_v291,
                    row.get(_col_blob_v291, _padrao_blob_v291),
                )
            return {
                "minha_empresa": row.get("minha_empresa", {}),
                "concorrentes": row.get("concorrentes", []),
                "metricas_redes": row.get("metricas_redes", {}),
                "ads_cache": row.get("ads_cache", {}),
                "analises_salvas": row.get("analises_salvas", []),
                "redes_analises_salvas": row.get("redes_analises_salvas", []),
                "ads_analises_salvas": row.get("ads_analises_salvas", []),
                "seo_cache": row.get("seo_cache", {}),
            }
    except Exception:
        pass
    return {
        "minha_empresa": {
            "nome": "", "setor": "Marketing", "tipo": "",
            "estado": "", "cidade": "",
            "instagram": "@", "fb_page": "", "site": "",
            "servicos": [], "ads_id": "", "ads_page_pic": ""
        },
        "concorrentes": [],
        "metricas_redes": {},
        "ads_cache": {},
        "analises_salvas": [],
        "redes_analises_salvas": [],
        "ads_analises_salvas": [],
    }

