import threading

def _empresa_ainda_valida(user_id: str, empresa_nome: str, query_usada: str, plataforma: str = "Meta Ads") -> bool:
    """Confere, direto no banco, se a empresa ainda está configurada com
    a mesma query/ads_id usada nessa coleta. Evita gastar banda e cota
    de mídia processando uma empresa que o usuário já corrigiu ou
    removeu logo depois de pedir a busca por engano.

    IMPORTANTE: Meta Ads e Google Ads guardam o ID configurado em campos
    DIFERENTES da empresa (`ads_id` pro Meta, `gads_id` pro Google — ver
    salvar_ads_id/salvar_gads_id). Antes esta função checava sempre
    `ads_id`, mesmo quando chamada pra uma migração de Google Ads. Numa
    empresa com um `ads_id` (Meta) configurado, isso nunca batia com o
    `query_usada` do Google, então TODA migração de Google Ads dessa
    empresa era descartada como "não é mais válida" antes de sequer
    tentar subir qualquer mídia pro R2 — mesmo a empresa nunca tendo
    mudado de fato."""
    try:
        res = (
            supabase.table("ci_dados")
            .select("minha_empresa, concorrentes")
            .eq("user_id", user_id)
            .execute()
        )
        if not res.data:
            return False
        row = res.data[0]
        candidatos = [row.get("minha_empresa") or {}] + (row.get("concorrentes") or [])
        campo_id = "gads_id" if plataforma == "Google Ads" else "ads_id"
        for c in candidatos:
            if c.get("nome") != empresa_nome:
                continue
            id_atual = (c.get(campo_id) or "").strip()
            return (not id_atual) or (id_atual == query_usada)
        return False  # nome não existe mais na configuração do usuário
    except Exception:
        return True  # checagem é só economia — em dúvida, não bloqueia

def _contar_midias_travadas_no_teto(user_id: str, empresa: str) -> int:
    """Conta quantas URLs de mídia dessa empresa já bateram no teto de
    MAX_TENTATIVAS_MIDIA tentativas em midias_falhas — ou seja,
    baixar_e_persistir_midia já desiste delas de cara (nem tenta baixar
    de novo, ver o `if ... >= MAX_TENTATIVAS_MIDIA: return url_origem`
    lá dentro). Usado logo abaixo pra distinguir "ainda vale a pena
    deixar o retry automático tentar de novo" de "travado de vez —
    precisa de link novo (nova coleta), retry não resolve"."""
    try:
        res = (
            supabase.table("midias_falhas")
            .select("id", count="exact")
            .eq("user_id", user_id)
            .eq("empresa", empresa)
            .gte("tentativas", MAX_TENTATIVAS_MIDIA)
            .execute()
        )
        return res.count or 0
    except Exception:
        return 0

_lock_migracao_empresa_ativa = threading.Lock()

@st.cache_resource
def _get_migracoes_empresa_ativas_agora() -> set:
    return set()

_migracoes_empresa_ativas_agora = _get_migracoes_empresa_ativas_agora()  # elementos: (user_id, empresa)

def _migracao_empresa_esta_ativa_agora(user_id: str, empresa: str) -> bool:
    with _lock_migracao_empresa_ativa:
        return (user_id, empresa) in _migracoes_empresa_ativas_agora

_RPC_ATUALIZAR_CACHE = {
    "Meta Ads": "atualizar_ads_no_cache",
    "Google Ads": "atualizar_gads_no_cache",
}
_RPC_SUBSTITUIR_URL_CACHE = {
    "Meta Ads": "substituir_url_no_ads_cache",
    "Google Ads": "substituir_url_no_gads_cache",
}

def _rpc_atualizar_cache(plataforma: str) -> str:
    return _RPC_ATUALIZAR_CACHE.get(plataforma, "atualizar_ads_no_cache")

def _rpc_substituir_url_cache(plataforma: str) -> str:
    return _RPC_SUBSTITUIR_URL_CACHE.get(plataforma, "substituir_url_no_ads_cache")

def _plataforma_da_url(url: str) -> str:
    """Quando a origem (migração pontual) não é conhecida — caso da
    reconciliação e da retentativa, que trabalham a partir das tabelas
    `midias`/`midias_falhas` e não guardam a plataforma — infere pelo
    domínio da própria URL original. Mesma heurística que já era usada
    só pra fins de log em _tentar_novamente_midias_background."""
    if url and ("googlesyndication.com" in url or "googleusercontent.com" in url):
        return "Google Ads"
    return "Meta Ads"

def _migrar_midia_background(user_id: str, empresa: str, entry: dict, atividade_id: str = None, plataforma: str = "Meta Ads"):
    _chave_ativa = (user_id, empresa)
    with _lock_migracao_empresa_ativa:
        _migracoes_empresa_ativas_agora.add(_chave_ativa)
    print(f"[MIGR-DEBUG] _migrar_midia_background INICIOU: empresa={empresa!r} atividade_id={atividade_id!r} r2_client_is_none={r2_client is None}", flush=True)
    try:
        if not _empresa_ainda_valida(user_id, empresa, entry.get("query", ""), plataforma):
            print(f"[MIGR-DEBUG] _migrar_midia_background SAIU: empresa={empresa!r} não é mais válida (alterada/removida)", flush=True)
            atualizar_atividade(atividade_id, "erro", {"empresa": empresa, "plataforma": plataforma, "motivo": "empresa alterada/removida antes da migração"})
            return

        _dados_para_migrar = {empresa: entry}
        if plataforma == "Google Ads":
            _dados_para_migrar = _enriquecer_gads_com_cc_youtube_v150(_dados_para_migrar)
        migrado, stats_midia = persistir_midias_de_ads(
            _dados_para_migrar, user_id, atividade_id=atividade_id, plataforma=plataforma
        )
        print(f"[MIGR-DEBUG] _migrar_midia_background persistir_midias_de_ads concluiu: empresa={empresa!r} stats={stats_midia}", flush=True)

        iniciar_transcricao_pendente_background(user_id, empresa)

        iniciar_ocr_pendente_background(user_id, empresa)

        _ads_migrado_empresa = migrado.get(empresa, {}).get("data", [])
        for _ad_mig in _ads_migrado_empresa:
            if not _imagem_precisa_de_b64_provisorio(_ad_mig):
                _ad_mig.pop("images_b64", None)
        atualizacoes = {
            str(ad["id"]): ad for ad in _ads_migrado_empresa if ad.get("id")
        }
        if not atualizacoes:
            atualizar_atividade(atividade_id, "concluido", {"empresa": empresa, "plataforma": plataforma, "motivo": "nenhum anúncio com id pra atualizar"})
            return

        if plataforma == "Google Ads":
            _canonico_atual = dict(
                (_carregar_checkpoints_gads_r2(user_id).get(empresa) or {})
            )
            _entry_r2_migrada = dict(_canonico_atual or entry or {})
            _dados_atuais = [
                dict(_ad) for _ad in (_entry_r2_migrada.get("data") or [])
                if isinstance(_ad, dict)
            ]
            _migrados_por_id = {
                str(_ad.get("id")): _ad
                for _ad in _ads_migrado_empresa
                if isinstance(_ad, dict) and _ad.get("id")
            }
            _campos_midia = {
                "images", "carousel_images", "images_b64",
                "page_profile_picture", "videos", "video_thumb", "video_url",
                "ocr_texto", "ocr_estruturado", "origem_texto", "transcricao",
                "video_cc_raw", "video_cc_status", "video_cc_texto",
                "video_cc_idioma", "video_cc_origem", "video_cc_metodo",
                "video_cc_motivo",
            }
            _ids_atuais = set()
            _atualizados = 0
            for _ad_atual in _dados_atuais:
                _ad_id = str(_ad_atual.get("id") or "")
                if not _ad_id:
                    continue
                _ids_atuais.add(_ad_id)
                _ad_processado = _migrados_por_id.get(_ad_id)
                if not _ad_processado:
                    continue
                for _campo, _valor in _ad_processado.items():
                    if _campo in _campos_midia or _campo.startswith("video_cc"):
                        _ad_atual[_campo] = _valor
                _atualizados += 1
            for _ad_id, _ad_processado in _migrados_por_id.items():
                if _ad_id not in _ids_atuais:
                    _dados_atuais.append(dict(_ad_processado))
                    _ids_atuais.add(_ad_id)
            _entry_r2_migrada["data"] = _dados_atuais
            _entry_r2_migrada["_checkpoint_finalizado"] = bool(
                _canonico_atual.get("_checkpoint_finalizado", True)
            )
            _entry_r2_migrada["_atividade_id"] = (
                _canonico_atual.get("_atividade_id")
                or (entry or {}).get("_atividade_id")
                or _entry_r2_migrada.get("_atividade_id")
            )
            print(
                f"[GADS-R2-V234] merge seguro empresa={empresa!r} "
                f"preservados={len(_dados_atuais)} atualizados={_atualizados}",
                flush=True,
            )
            _ok_r2_migracao, _erro_r2_migracao = _salvar_checkpoint_gads_r2(
                user_id, empresa, _entry_r2_migrada
            )
            if not _ok_r2_migracao:
                atualizar_atividade(atividade_id, "erro", {
                    "empresa": empresa,
                    "plataforma": plataforma,
                    "motivo": f"Mídias processadas, mas o cache por empresa não foi atualizado: {_erro_r2_migracao}",
                })
                return
            _salvar_manifesto_gads_json_v261(
                user_id, motivo=f"armazenamento_concluido:{empresa}"
            )
            iniciar_ocr_pendente_background(user_id, empresa)
            _total_r2 = int(stats_midia.get("total", 0) or 0)
            _falhas_r2 = int(stats_midia.get("nao_migrados", 0) or 0)
            atualizar_atividade(
                atividade_id,
                "em_andamento" if _falhas_r2 else "concluido",
                {
                    "empresa": empresa,
                    "plataforma": plataforma,
                    "total": _total_r2,
                    "migradas": max(0, _total_r2 - _falhas_r2),
                    "nao_migradas": _falhas_r2,
                    "armazenamento_principal": "r2_por_empresa",
                    "ultima_tentativa_em": _agora_iso(),
                    "aviso": (
                        f"{max(0, _total_r2 - _falhas_r2)} de {_total_r2} mídia(s) "
                        f"salvas; {_falhas_r2} ainda aguardam nova tentativa."
                        if _falhas_r2 else ""
                    ),
                    "motivo": (
                        f"{_falhas_r2} mídia(s) ainda aguardam nova tentativa."
                        if _falhas_r2 else "Mídias confirmadas no cache por empresa."
                    ),
                },
            )
            print(f"[GADS-R2-V233] mídia atualizada no cache canônico empresa={empresa!r}", flush=True)
            return

        res = supabase.rpc(_rpc_atualizar_cache(plataforma), {
            "p_user_id": user_id,
            "p_empresa": empresa,
            "p_atualizacoes": atualizacoes,
        }).execute()

        if res.data:
            total = stats_midia.get("total", 0)
            nao_migrados = stats_midia.get("nao_migrados", 0)
            migradas = total - nao_migrados
            if nao_migrados:
                _travadas_no_teto = _contar_midias_travadas_no_teto(user_id, empresa)
                _cota_esgotada = (_travadas_no_teto < nao_migrados) and not pode_baixar_midia(user_id)
                if _travadas_no_teto >= nao_migrados:
                    status_final = "erro"
                    detalhes_finais = {
                        "empresa": empresa,
                        "plataforma": plataforma,
                        "migradas": migradas,
                        "total": total,
                        "motivo": (
                            f"{nao_migrados} anúncios têm links do Facebook que já expiraram "
                            f"e esgotaram as {MAX_TENTATIVAS_MIDIA} tentativas automáticas de "
                            f"download — não vão se resolver sozinhos. É preciso uma nova "
                            f"coleta desta empresa pra pegar links atualizados antes de "
                            f"migrar de novo."
                        ),
                        "anuncios_com_erro": stats_midia.get("anuncios_com_erro", []),
                        "total_anuncios_com_erro": stats_midia.get("total_anuncios_com_erro", 0),
                        "anuncios_migrados": stats_midia.get("anuncios_migrados", []),
                        "total_anuncios_migrados": stats_midia.get("total_anuncios_migrados", 0),
                    }
                elif _cota_esgotada:
                    _limite_cota = PLANOS_QUOTA_MIDIAS.get(obter_plano_usuario())
                    status_final = "erro"
                    detalhes_finais = {
                        "empresa": empresa,
                        "plataforma": plataforma,
                        "migradas": migradas,
                        "total": total,
                        "cota_esgotada": True,
                        "motivo": (
                            f"{nao_migrados} anúncios ainda não foram migrados porque a cota "
                            f"mensal de anúncios com mídia do seu plano "
                            f"({_limite_cota if _limite_cota is not None else '∞'}/mês) foi "
                            f"atingida. Isso não é uma falha passageira — o retry automático "
                            f"não resolve sozinho. A migração retoma no início do próximo "
                            f"ciclo ou assim que o plano for atualizado; até lá, use o botão "
                            f"'Refazer' quando quiser tentar de novo manualmente."
                        ),
                        "anuncios_com_erro": stats_midia.get("anuncios_com_erro", []),
                        "total_anuncios_com_erro": stats_midia.get("total_anuncios_com_erro", 0),
                        "anuncios_migrados": stats_midia.get("anuncios_migrados", []),
                        "total_anuncios_migrados": stats_midia.get("total_anuncios_migrados", 0),
                    }
                else:
                    status_final = "em_andamento"
                    detalhes_finais = {
                        "empresa": empresa,
                        "plataforma": plataforma,
                        "migradas": migradas,
                        "total": total,
                        "aviso": (
                            f"{migradas} de {total} anúncios salvos na Biblioteca de Arquivos "
                            f"Permanente — {nao_migrados} ainda pendentes (link original expira; "
                            f"vamos tentar de novo automaticamente)"
                        ),
                        "amostra": stats_midia.get("amostra_nao_migrados", []),
                        "anuncios_com_erro": stats_midia.get("anuncios_com_erro", []),
                        "total_anuncios_com_erro": stats_midia.get("total_anuncios_com_erro", 0),
                        "anuncios_migrados": stats_midia.get("anuncios_migrados", []),
                        "total_anuncios_migrados": stats_midia.get("total_anuncios_migrados", 0),
                        "ultima_tentativa_em": _agora_iso(),
                    }
            elif total:
                status_final = "concluido"
                detalhes_finais = {
                    "empresa": empresa,
                    "plataforma": plataforma,
                    "migradas": total,
                    "total": total,
                    "anuncios_migrados": stats_midia.get("anuncios_migrados", []),
                    "total_anuncios_migrados": stats_midia.get("total_anuncios_migrados", 0),
                }
            else:
                status_final = "concluido"
                detalhes_finais = {"empresa": empresa, "plataforma": plataforma}
            atualizar_atividade(atividade_id, status_final, detalhes_finais)
        else:
            atualizar_atividade(atividade_id, "erro", {"empresa": empresa, "plataforma": plataforma, "motivo": "empresa não encontrada no ads_cache no momento da atualização"})
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"empresa": empresa, "plataforma": plataforma, "motivo": str(e)})
    finally:
        with _lock_migracao_empresa_ativa:
            _migracoes_empresa_ativas_agora.discard(_chave_ativa)

def _estimar_timeout_migracao(entry: dict) -> int:
    """Calcula um limite de tempo proporcional à quantidade de mídia
    dessa empresa, em vez de um número fixo — uma empresa com poucas
    imagens não devia ganhar 20 minutos de crédito de dúvida, e uma com
    muitos vídeos pode legitimamente precisar de mais que isso."""
    ads = entry.get("data", [])
    n_imagens = sum(len(a.get("images") or []) for a in ads)
    n_videos = sum(len(a.get("videos") or []) for a in ads)

    SEGUNDOS_POR_IMAGEM = 20
    SEGUNDOS_POR_VIDEO = 60
    PARALELISMO = 1  # migração pesada é deliberadamente serial

    tempo_estimado = (n_imagens * SEGUNDOS_POR_IMAGEM + n_videos * SEGUNDOS_POR_VIDEO) / PARALELISMO
    return int(max(180, min(tempo_estimado, 3600)))  # piso 3 min, teto 1 h

def _migrar_todas_empresas_sequencial(user_id: str, tarefas: list):
    """Executa migrações uma por vez e na mesma fila pesada do OCR.

    Se OCR estiver rodando, esta função espera sem iniciar downloads,
    ffmpeg, modelos ou qualquer outra etapa pesada. Quando o OCR termina,
    a sequência completa de migrações é liberada. Enquanto a migração
    estiver ativa, novos OCRs aguardam.
    """
    if not tarefas:
        return

    _plataformas = sorted({str(t[3]) for t in tarefas})
    _detalhe = f"{', '.join(_plataformas)} · {len(tarefas)} empresa(s)"

    if _fila_pesada_esta_ocupada():
        for empresa, _entry, atividade_id, plataforma in tarefas:
            try:
                atualizar_atividade(
                    atividade_id,
                    "em_andamento",
                    {
                        "empresa": empresa,
                        "plataforma": plataforma,
                        "aguardando_fila_pesada": True,
                        "aviso": "Aguardando a ação atual terminar para iniciar a migração de mídia.",
                    },
                )
            except Exception:
                pass

    _ticket_fila_pesada = None
    try:
        _esperar_coleta_prioritaria_v195(user_id, "MIGRAÇÃO")
        _esperar_outra_acao_pesada_persistente(
            user_id,
            excluir_tipos=("migracao_midia",),
            atividade_ids_espera=[t[2] for t in tarefas],
            descricao=f"MIGRAÇÃO {_detalhe}",
        )

        _ticket_fila_pesada = _entrar_fila_acao_pesada("MIGRAÇÃO", _detalhe)

        print(
            f"[MIGR-DEBUG] migração liberada pela fila pesada: "
            f"{[t[0] for t in tarefas]}",
            flush=True,
        )

        for empresa, entry, atividade_id, plataforma in tarefas:
            try:
                try:
                    atualizar_atividade(
                        atividade_id,
                        "em_andamento",
                        {
                            "empresa": empresa,
                            "plataforma": plataforma,
                            "aguardando_fila_pesada": False,
                            "aviso": "Migração de mídia em processamento.",
                        },
                    )
                except Exception:
                    pass

                try:
                    _migrar_midia_background(
                        user_id,
                        empresa,
                        entry,
                        atividade_id,
                        plataforma,
                    )
                except Exception as e:
                    atualizar_atividade(
                        atividade_id,
                        "erro",
                        {
                            "empresa": empresa,
                            "plataforma": plataforma,
                            "motivo": str(e),
                        },
                    )
            finally:
                _job_release(
                    "migracao_midia",
                    user_id,
                    f"{plataforma}:{empresa}",
                )

        if "Google Ads" in _plataformas:
            try:
                _cache_pos_coleta_v259 = _carregar_checkpoints_gads_r2(user_id) or {}
                _pendentes_pos_coleta_v259 = _encontrar_imagens_gads_pendentes_v257(
                    _cache_pos_coleta_v259
                )
                if _pendentes_pos_coleta_v259:
                    _total_pendentes_v259 = sum(
                        len((_entry or {}).get("data") or [])
                        for _entry in _pendentes_pos_coleta_v259.values()
                    )
                    _atividade_pos_coleta_v259 = criar_atividade(
                        user_id,
                        "verificacao_pendentes_gads",
                        "Conferindo armazenamento geral dos anúncios do Google Ads",
                        {
                            "versao_forcamento": "V259",
                            "anuncios_pendentes": _total_pendentes_v259,
                            "aviso": (
                                "A coleta terminou. Conferindo no inventário geral "
                                "as imagens salvas e refazendo as pendentes."
                            ),
                        },
                    )
                    _reparar_imagens_visiveis_com_relogio_v258(
                        user_id,
                        _cache_pos_coleta_v259,
                        _atividade_pos_coleta_v259,
                    )
                else:
                    _salvar_manifesto_gads_json_v261(
                        user_id,
                        _cache_pos_coleta_v259,
                        motivo="conferencia_geral_pos_coleta",
                    )
            except Exception as _exc_pos_coleta_v259:
                print(
                    f"[GADS-XML-V259] conferência geral pós-coleta falhou: "
                    f"{_exc_pos_coleta_v259!r}",
                    flush=True,
                )
    finally:
        if _ticket_fila_pesada is not None:
            _sair_fila_acao_pesada(_ticket_fila_pesada)


def iniciar_migracao_midia_background(user_id: str, novos: dict, plataforma: str = "Meta Ads"):
    """Migra as mídias das empresas recém-coletadas pro R2, sem travar
    a página. As empresas são processadas uma de cada vez (não em
    paralelo) — ver _migrar_todas_empresas_sequencial.

    `plataforma` ("Meta Ads" ou "Google Ads") entra no título e nos
    detalhes da atividade — sem isso não dava pra saber, só olhando o
    sino de notificações, se um card "Salvando anúncios na Biblioteca
    de Arquivos Permanente" era do Meta ou do Google, e pior: duas
    empresas com o mesmo nome em plataformas diferentes acabavam
    compartilhando a MESMA atividade (ver _atividade_migracao_mais_
    recente_id), misturando o progresso de uma migração com o da outra.

    Antes de criar uma atividade nova, verifica se já existe QUALQUER
    atividade migracao_midia pra essa mesma empresa NESSA MESMA
    plataforma (não importa o status) e reaproveita o id — assim ela
    vira só um "empurrão" na mesma notificação em vez de um card novo.
    Antes disso só reaproveitava quando a atividade estava pendente/
    em_andamento; se ela já tivesse fechado como 'concluído' e a
    empresa voltasse a ter mídia pendente depois (nova coleta, ou uma
    varredura achando itens antigos), o sino ganhava um card duplicado
    pra sempre 'em andamento' em vez de continuar atualizando o
    mesmo."""
    tarefas = []
    for empresa, entry in novos.items():
        _escopo_job_migr = f"{plataforma}:{empresa}"
        if not _job_try_acquire("migracao_midia", user_id, _escopo_job_migr):
            print(f"[MIGR-DEBUG] ignorado job duplicado empresa={empresa!r} plataforma={plataforma!r}", flush=True)
            continue
        atividade_id = _atividade_migracao_mais_recente_id(user_id, empresa, plataforma)
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {"empresa": empresa, "plataforma": plataforma})
        else:
            atividade_id = criar_atividade(
                user_id, "migracao_midia",
                f"{empresa} · Salvando anúncios do {plataforma} na Biblioteca de Arquivos Permanente",
                {"empresa": empresa, "plataforma": plataforma},
            )
        tarefas.append((empresa, entry, atividade_id, plataforma))

    print(f"[MIGR-DEBUG] iniciar_migracao_midia_background: {len(tarefas)} empresa(s) na fila -> {[t[0] for t in tarefas]} (plataforma={plataforma!r})", flush=True)
    if tarefas:
        threading.Thread(
            target=_migrar_todas_empresas_sequencial,
            args=(user_id, tarefas),
            daemon=True,
        ).start()

def encontrar_ads_com_link_original(
    ads_cache: dict, *, incluir_foto_perfil: bool = True
) -> dict:
    """Varre o ads_cache inteiro (todas as empresas, todos os anúncios)
    procurando qualquer mídia que ainda aponte pro link original da Meta
    (não migrado pro R2) — não importa se é recente, antigo, se a
    migração nunca rodou, ou se rodou e falhou silenciosamente. Devolve
    só os anúncios pendentes, no mesmo formato que iniciar_migracao_
    midia_background espera (pra reaproveitar o mesmo pipeline).

    Quando o anúncio TEM vídeo, só o(s) link(s) de vídeo entram nessa
    verificação — as imagens (`images`) são ignoradas nesse caso. Isso
    não é um descuido: no card de anúncios, o thumb de um anúncio com
    vídeo nunca vem do campo `images` — vem do próprio `<video>` sendo
    avançado pra um frame (`onloadedmetadata="this.currentTime=2.5"`).
    As imagens desse tipo de anúncio (comum em campanhas "Dinâmicas",
    onde a Meta testa variações de criativo) só aparecem mesmo dentro do
    modal opcional "🖼️ +N", que já tem seu próprio fallback caso a
    imagem tenha quebrado. Ou seja: um link de imagem expirado nesse
    caso não quebra nada que o usuário veja por padrão — só contava
    como "urgente" antes por engano, inflando o card de Links da Meta
    (e disparando migração) por uma mídia que não é a que realmente
    sustenta a experiência. Só quando o anúncio NÃO tem vídeo (é uma
    imagem "de verdade", a mídia principal) é que as imagens voltam a
    contar normalmente."""
    pendentes = {}
    for empresa, entry in (ads_cache or {}).items():
        ads_pendentes = []
        for ad in entry.get("data", []) or []:
            imagens = ad.get("images") or []
            videos = ad.get("videos") or []
            midias_relevantes = videos if videos else imagens
            foto_perfil = ad.get("page_profile_picture")
            if incluir_foto_perfil and foto_perfil:
                midias_relevantes = list(midias_relevantes) + [foto_perfil]
            tem_link_original = any(
                u and not (R2_PUBLIC_BASE and u.startswith(R2_PUBLIC_BASE))
                for u in midias_relevantes
            )
            if tem_link_original:
                ads_pendentes.append(ad)
        if ads_pendentes:
            pendentes[empresa] = {**entry, "data": ads_pendentes}
    return pendentes


def _reconectar_gads_r2_com_midias_salvas_v256(
    user_id: str, gads_cache: dict, atividade_id: str = None
) -> tuple[dict, int]:
    """Troca referências originais do cache canônico pelas URLs já salvas.

    Algumas execuções antigas concluíram o upload e criaram corretamente a
    linha em ``midias``, mas o checkpoint por empresa continuou apontando para
    a URL do Google. O card então usava o base64 como fallback, mostrava o
    relógio e não encontrava o OCR, que é indexado por ``url_cdn``.

    A V256 reconhece base64 tanto em ``images_b64`` quanto diretamente em
    ``images``. Quando recebe uma URL HTTP, mantém o download seletivo da V255.
    Não envia arquivo, não comprime e não roda OCR novamente.
    """
    if not gads_cache:
        return gads_cache or {}, 0

    try:
        _res_midias = _supabase_resiliente(
            lambda: (
                supabase.table("midias")
                .select("empresa,ad_id,tipo,url_origem,url_cdn,hash_conteudo")
                .eq("user_id", user_id)
                .execute()
            ),
            operacao="reconectar_gads_r2_v256",
            tentativas=3,
        )
        _linhas = _res_midias.data or []
    except Exception as _exc:
        print(f"[GADS-R2-V256] índice de mídias indisponível: {_exc!r}", flush=True)
        return gads_cache, 0

    def _chave_url(_url: str) -> str:
        _u = str(_url or "").strip()
        if not _u:
            return ""
        try:
            from urllib.parse import urlsplit
            _p = urlsplit(_u)
            _host = (_p.hostname or "").lower()
            if "google" in _host or "doubleclick" in _host:
                return f"{_host}{_p.path}"
        except Exception:
            pass
        return _u

    _por_origem = {}
    _por_ad_tipo = {}
    _por_hash = {}
    for _m in _linhas:
        _origem = str(_m.get("url_origem") or "").strip()
        _cdn = str(_m.get("url_cdn") or "").strip()
        if not _cdn:
            continue
        _empresa = str(_m.get("empresa") or "")
        _ad_id = str(_m.get("ad_id") or "")
        _tipo = str(_m.get("tipo") or "imagem")
        _hash = str(_m.get("hash_conteudo") or "").strip().lower()
        if _hash:
            _por_hash[_hash] = _cdn
        if _origem and _origem != _cdn:
            _por_origem[(_empresa, _ad_id, _tipo, _chave_url(_origem))] = _cdn
            _por_origem.setdefault(("", "", _tipo, _chave_url(_origem)), _cdn)
        if _empresa and _ad_id:
            _por_ad_tipo.setdefault((_empresa, _ad_id, _tipo), set()).add(_cdn)

    _downloads_v255 = 0
    _falhas_download_v255 = 0
    _matches_hash_v255 = 0
    _data_uri_lidas_v256 = 0
    _data_uri_matches_v256 = 0
    _data_uri_sem_hash_v256 = 0
    _resultado_url_v255 = {}
    _total_urls_v255 = sum(
        1
        for _entry in (gads_cache or {}).values()
        for _ad in ((_entry or {}).get("data") or [])
        for _url in ((_ad or {}).get("images") or [])
        if str(_url or "").startswith(("http://", "https://", "data:"))
        and not (R2_PUBLIC_BASE and str(_url).startswith(R2_PUBLIC_BASE))
    )
    _verificadas_v255 = 0

    def _heartbeat_v255(_ad_id: str, _resultado: str) -> None:
        nonlocal _verificadas_v255
        _verificadas_v255 += 1
        if not atividade_id:
            return
        if _verificadas_v255 % 5 and _verificadas_v255 < _total_urls_v255:
            return
        try:
            atualizar_atividade(atividade_id, "em_andamento", {
                "etapa": "reconectando_por_hash",
                "etapa_atual": 2,
                "total_etapas": 3,
                "verificados": _verificadas_v255,
                "total_verificar": _total_urls_v255,
                "reconectados": _matches_hash_v255,
                "falhas_download": _falhas_download_v255,
                "anuncio_atual": _ad_id,
                "resultado_atual": _resultado,
                "aviso": (
                    f"Conferindo imagens já salvas: {_verificadas_v255} de "
                    f"{_total_urls_v255}. {_matches_hash_v255} reconectada(s)."
                ),
                "ultimo_heartbeat_em": _agora_iso(),
            })
        except Exception:
            pass

    def _cdn_por_hash_da_url_v255(_url: str, _ad_id: str, _referer: str = "") -> str:
        """Baixa só os bytes necessários ao vínculo; nunca persiste/upload."""
        nonlocal _downloads_v255, _falhas_download_v255, _matches_hash_v255
        _url = str(_url or "").strip()
        if _url in _resultado_url_v255:
            return _resultado_url_v255[_url]
        if not _url.startswith(("http://", "https://")):
            return ""
        if R2_PUBLIC_BASE and _url.startswith(R2_PUBLIC_BASE):
            return ""
        _ua = (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
        )
        _headers_lista = [
            {},
            {"User-Agent": _ua},
            {"User-Agent": _ua, "Referer": "https://adstransparency.google.com/"},
        ]
        if _referer:
            _headers_lista.append({"User-Agent": _ua, "Referer": _referer})
        for _headers in _headers_lista:
            try:
                with _recurso_api_io():
                    _resp = _http_get(_url, timeout=15, headers=_headers)
                _ct = str(_resp.headers.get("content-type") or "").lower()
                if _resp.status_code != 200 or not _resp.content or not _ct.startswith("image/"):
                    continue
                if len(_resp.content) > 20 * 1024 * 1024:
                    break
                _downloads_v255 += 1
                _hash = hashlib.sha256(_resp.content).hexdigest().lower()
                _cdn = _por_hash.get(_hash, "")
                if _cdn:
                    _matches_hash_v255 += 1
                    print(
                        f"[GADS-R2-V256] hash HTTP localizado ad={_ad_id!r} bytes={len(_resp.content)}",
                        flush=True,
                    )
                    _resultado_url_v255[_url] = _cdn
                    _heartbeat_v255(_ad_id, "reconectada")
                    return _cdn
                print(
                    f"[GADS-R2-V256] hash HTTP sem registro ad={_ad_id!r} hash={_hash[:12]}",
                    flush=True,
                )
                _resultado_url_v255[_url] = ""
                _heartbeat_v255(_ad_id, "hash_nao_encontrado")
                return ""
            except Exception as _exc_download:
                continue
        _falhas_download_v255 += 1
        _resultado_url_v255[_url] = ""
        _heartbeat_v255(_ad_id, "download_falhou")
        print(f"[GADS-R2-V256] download seletivo falhou ad={_ad_id!r}", flush=True)
        return ""

    def _cdn_por_data_uri_v256(_valor: str, _ad_id: str) -> str:
        """Resolve data URI já carregada no cache sem rede nem novo upload."""
        nonlocal _data_uri_lidas_v256, _data_uri_matches_v256
        nonlocal _data_uri_sem_hash_v256, _matches_hash_v255
        _txt = str(_valor or "")
        if not _txt.startswith("data:") or ";base64," not in _txt:
            return ""
        try:
            import base64 as _base64_v256
            _payload = _txt.split(";base64,", 1)[1]
            _bytes = _base64_v256.b64decode(_payload, validate=False)
            if not _bytes or len(_bytes) > 20 * 1024 * 1024:
                return ""
            _data_uri_lidas_v256 += 1
            _hash = hashlib.sha256(_bytes).hexdigest().lower()
            _cdn = _por_hash.get(_hash, "")
            if _cdn:
                _data_uri_matches_v256 += 1
                _matches_hash_v255 += 1
                print(
                    f"[GADS-R2-V256] data URI localizada ad={_ad_id!r} bytes={len(_bytes)}",
                    flush=True,
                )
                _heartbeat_v255(_ad_id, "data_uri_reconectada")
                return _cdn
            _data_uri_sem_hash_v256 += 1
            print(
                f"[GADS-R2-V256] data URI sem registro ad={_ad_id!r} hash={_hash[:12]}",
                flush=True,
            )
            _heartbeat_v255(_ad_id, "data_uri_sem_registro")
        except Exception as _exc_data_uri:
            print(
                f"[GADS-R2-V256] data URI inválida ad={_ad_id!r}: {_exc_data_uri!r}",
                flush=True,
            )
        return ""

    _cache_novo = copy.deepcopy(gads_cache)
    _total_trocas = 0
    _empresas_alteradas = []
    for _empresa, _entry in _cache_novo.items():
        _mudou_empresa = False
        _trocas_empresa = 0
        for _ad in (_entry.get("data") or []):
            if not isinstance(_ad, dict):
                continue
            _ad_id = str(_ad.get("id") or "")
            _cdns_por_base64 = set()
            for _b64_item in (_ad.get("images_b64") or []):
                _b64_txt = str(_b64_item or "")
                if not _b64_txt.startswith("data:") or ";base64," not in _b64_txt:
                    continue
                try:
                    import base64 as _base64_v254
                    _payload_v254 = _b64_txt.split(";base64,", 1)[1]
                    _bytes_v254 = _base64_v254.b64decode(_payload_v254, validate=False)
                    _hash_v254 = hashlib.sha256(_bytes_v254).hexdigest().lower()
                    _cdn_hash_v254 = _por_hash.get(_hash_v254)
                    if _cdn_hash_v254:
                        _cdns_por_base64.add(_cdn_hash_v254)
                except Exception:
                    continue
            for _campo, _tipo in (
                ("images", "imagem"),
                ("carousel_images", "imagem"),
                ("videos", "video"),
            ):
                _urls = list(_ad.get(_campo) or [])
                if not _urls:
                    continue
                _cdns_ad = _por_ad_tipo.get((str(_empresa), _ad_id, _tipo), set())
                for _idx, _url in enumerate(_urls):
                    if not _url or (R2_PUBLIC_BASE and str(_url).startswith(R2_PUBLIC_BASE)):
                        continue
                    _url_txt_v256 = str(_url)
                    if _tipo == "imagem" and _url_txt_v256.startswith("data:"):
                        _cdn = _cdn_por_data_uri_v256(_url_txt_v256, _ad_id)
                    else:
                        _cdn = (
                            _por_origem.get((str(_empresa), _ad_id, _tipo, _chave_url(_url)))
                            or _por_origem.get(("", "", _tipo, _chave_url(_url)))
                        )
                    if not _cdn and len(_cdns_ad) == 1:
                        _cdn = next(iter(_cdns_ad))
                    if not _cdn and _tipo == "imagem" and len(_cdns_por_base64) == 1:
                        _cdn = next(iter(_cdns_por_base64))
                    if not _cdn and _tipo == "imagem" and not _url_txt_v256.startswith("data:"):
                        _cdn = _cdn_por_hash_da_url_v255(
                            str(_url),
                            _ad_id,
                            str(_ad.get("snapshot_url") or _ad.get("creative_url") or ""),
                        )
                    if _cdn:
                        _urls[_idx] = _cdn
                        _trocas_empresa += 1
                        _mudou_empresa = True
                _ad[_campo] = _urls

            _imgs = [str(_u or "") for _u in (_ad.get("images") or []) if _u]
            if _imgs and R2_PUBLIC_BASE and all(_u.startswith(R2_PUBLIC_BASE) for _u in _imgs):
                _ad.pop("images_b64", None)

        if _mudou_empresa:
            _ok, _erro = _salvar_checkpoint_gads_r2(user_id, _empresa, _entry)
            if _ok:
                _total_trocas += _trocas_empresa
                _empresas_alteradas.append(str(_empresa))
            else:
                _cache_novo[_empresa] = copy.deepcopy(gads_cache.get(_empresa) or {})
                print(
                    f"[GADS-R2-V256] falha ao salvar reconciliação "
                    f"empresa={_empresa!r}: {_erro}",
                    flush=True,
                )

    print(
        f"[GADS-R2-V256] reconciliação concluída trocas={_total_trocas} "
        f"empresas={_empresas_alteradas} downloads={_downloads_v255} "
        f"matches_hash={_matches_hash_v255} falhas_download={_falhas_download_v255} "
        f"data_uri_lidas={_data_uri_lidas_v256} "
        f"data_uri_matches={_data_uri_matches_v256} "
        f"data_uri_sem_hash={_data_uri_sem_hash_v256}",
        flush=True,
    )
    return _cache_novo, _total_trocas


def _imagem_gads_exibe_relogio_v258(ad: dict) -> bool:
    """Replica literalmente a regra visual do card de Google Ads.

    O relógio amarelo pertence somente à imagem principal: ele aparece
    quando o anúncio tem ao menos uma imagem, mas nenhuma URL de ``images``
    aponta para o R2. Vídeos são links e não participam desta decisão.
    """
    _images = []
    for _campo_v273 in ("images_b64", "images", "carousel_images"):
        for _u_v273 in ((ad or {}).get(_campo_v273) or []):
            _u_v273 = str(_u_v273 or "").strip()
            if _u_v273 and _u_v273 not in _images:
                _images.append(_u_v273)
    if not _images:
        return False
    if _gads_ad_eh_video_v267(ad):
        return False
    return not (
        R2_PUBLIC_BASE
        and any(_u.startswith(R2_PUBLIC_BASE) for _u in _images)
    )


def _encontrar_imagens_gads_pendentes_v257(gads_cache: dict) -> dict:
    """Seleciona exatamente os anúncios cujo card exibe o relógio."""
    _out = {}
    for _empresa, _entry in (gads_cache or {}).items():
        _ads = []
        for _ad in ((_entry or {}).get("data") or []):
            if _imagem_gads_exibe_relogio_v258(_ad):
                _ads.append(_ad)
        if _ads:
            _out[_empresa] = {**(_entry or {}), "data": _ads}
    return _out


def _persistir_data_uri_imagem_gads_v273(
    data_uri: str, user_id: str, empresa: str, ad_id: str = ""
) -> str:
    """Salva no R2 uma captura visual `data:image/...;base64,...`."""
    if not str(data_uri or "").startswith("data:image/"):
        return data_uri
    if r2_client is None or not pode_baixar_midia(user_id):
        return data_uri
    try:
        _cabecalho_v273, _payload_v273 = str(data_uri).split(",", 1)
        if ";base64" not in _cabecalho_v273.lower():
            return data_uri
        _mime_v273 = _cabecalho_v273[5:].split(";", 1)[0].strip().lower()
        if not _mime_v273.startswith("image/"):
            return data_uri
        _conteudo_v273 = base64.b64decode(_payload_v273, validate=False)
        if not _conteudo_v273:
            return data_uri
        _hash_v273 = hashlib.sha256(_conteudo_v273).hexdigest()

        _existente_v273 = (
            supabase.table("midias")
            .select("url_cdn")
            .eq("user_id", user_id)
            .eq("hash_conteudo", _hash_v273)
            .limit(1)
            .execute()
        )
        if _existente_v273.data:
            _url_existente_v273 = str(
                _existente_v273.data[0].get("url_cdn") or ""
            )
            if _url_existente_v273:
                return _url_existente_v273

        _upload_v273, _mime_upload_v273, _ext_v273 = _comprimir_imagem(
            _conteudo_v273, _mime_v273
        )
        if not _ext_v273:
            _ext_v273 = mimetypes.guess_extension(_mime_upload_v273) or ".webp"
        _storage_v273 = (
            f"{user_id}/{_slug_empresa(empresa)}/{_hash_v273}{_ext_v273}"
        )
        r2_client.put_object(
            Bucket=R2_BUCKET,
            Key=_storage_v273,
            Body=_upload_v273,
            ContentType=_mime_upload_v273,
        )
        _url_cdn_v273 = f"{R2_PUBLIC_BASE}/{_storage_v273}"
        supabase.table("midias").insert({
            "user_id": user_id,
            "empresa": empresa,
            "ad_id": ad_id or None,
            "tipo": "imagem",
            "url_origem": f"captura_visual:{ad_id}:{_hash_v273}",
            "storage_key": _storage_v273,
            "url_cdn": _url_cdn_v273,
            "mime_type": _mime_upload_v273,
            "tamanho_bytes": len(_upload_v273),
            "hash_conteudo": _hash_v273,
            "ocr_texto": None,
            "ocr_estruturado": None,
        }).execute()
        print(
            f"[GADS-R2-V273] captura salva empresa={empresa!r} "
            f"ad_id={ad_id!r} url={_url_cdn_v273!r}",
            flush=True,
        )
        return _url_cdn_v273
    except Exception as _exc_v273:
        print(
            f"[GADS-R2-V273] falha ao salvar captura empresa={empresa!r} "
            f"ad_id={ad_id!r}: {_exc_v273!r}",
            flush=True,
        )
        return data_uri


def _forcar_armazenamento_imagens_gads_v257(
    user_id: str, gads_cache: dict, atividade_id: str = None
) -> tuple[dict, dict]:
    """Restaura o salvamento forçado, restrito às imagens com relógio.

    Usa o pipeline consolidado de mídia, que já aplica deduplicação, cota,
    limite de tentativas e registro de falhas. Vídeos e demais campos do
    anúncio não são tocados.
    """
    _cache = copy.deepcopy(gads_cache or {})
    _pendentes = _encontrar_imagens_gads_pendentes_v257(_cache)
    _total = sum(
        1
        for _entry in _pendentes.values()
        for _ad in (_entry.get("data") or [])
        for _campo in ("images_b64", "images", "carousel_images")
        for _u in (_ad.get(_campo) or [])
        if str(_u or "").startswith(("http://", "https://", "data:"))
        and not (R2_PUBLIC_BASE and str(_u).startswith(R2_PUBLIC_BASE))
    )
    _feitas = 0
    _salvas = 0
    _falhas = 0
    _empresas_salvas = []
    _memo_url = {}

    for _empresa, _entry in _pendentes.items():
        _mudou_empresa = False
        for _ad in (_entry.get("data") or []):
            _ad_id = str(_ad.get("id") or "")
            _referer = str(_ad.get("snapshot_url") or _ad.get("creative_url") or "")
            for _campo in ("images_b64", "images", "carousel_images"):
                _urls = list(_ad.get(_campo) or [])
                for _idx, _url in enumerate(_urls):
                    _url = str(_url or "")
                    if not _url or (R2_PUBLIC_BASE and _url.startswith(R2_PUBLIC_BASE)):
                        continue
                    if not _url.startswith(("http://", "https://", "data:")):
                        continue
                    _feitas += 1
                    _nova = _memo_url.get(_url)
                    if _nova is None:
                        if _url.startswith("data:"):
                            _nova = _persistir_data_uri_imagem_gads_v273(
                                _url, user_id, str(_empresa), _ad_id
                            )
                        else:
                            _nova = baixar_e_persistir_midia(
                                _url, user_id, str(_empresa), "imagem",
                                ad_id=_ad_id, referer_hint=_referer,
                            )
                        _memo_url[_url] = _nova
                    if _nova and _nova != _url and (
                        not R2_PUBLIC_BASE or str(_nova).startswith(R2_PUBLIC_BASE)
                    ):
                        _urls[_idx] = _nova
                        _salvas += 1
                        _mudou_empresa = True
                    else:
                        _falhas += 1
                    if atividade_id and (_feitas % 5 == 0 or _feitas == _total):
                        atualizar_atividade(atividade_id, "em_andamento", {
                            "versao_forcamento": "V257",
                            "etapa": "armazenando_imagens_pendentes",
                            "etapa_atual": 3,
                            "total_etapas": 3,
                            "processadas": _feitas,
                            "total_imagens": _total,
                            "salvas": _salvas,
                            "falhas": _falhas,
                            "empresa_atual": _empresa,
                            "anuncio_atual": _ad_id,
                            "aviso": (
                                f"Salvando imagens com relógio: {_feitas} de {_total}. "
                                f"{_salvas} salva(s); {_falhas} ainda pendente(s)."
                            ),
                            "ultimo_heartbeat_em": _agora_iso(),
                        })
                _ad[_campo] = _urls
            _imgs = [str(_u or "") for _u in (_ad.get("images") or []) if _u]
            if _imgs and R2_PUBLIC_BASE and all(_u.startswith(R2_PUBLIC_BASE) for _u in _imgs):
                _ad.pop("images_b64", None)

        if _mudou_empresa:
            _ok, _erro = _salvar_checkpoint_gads_r2(user_id, _empresa, _cache[_empresa])
            if _ok:
                _empresas_salvas.append(str(_empresa))
                iniciar_ocr_pendente_background(user_id, str(_empresa))
            else:
                _falhas += 1
                print(
                    f"[GADS-R2-V257] falha ao salvar checkpoint empresa={_empresa!r}: {_erro}",
                    flush=True,
                )

    _stats = {
        "total": _total,
        "processadas": _feitas,
        "salvas": _salvas,
        "falhas": _falhas,
        "empresas": _empresas_salvas,
    }
    print(f"[GADS-R2-V257] armazenamento forçado concluído stats={_stats}", flush=True)
    return _cache, _stats


def _reparar_imagens_visiveis_com_relogio_v258(
    user_id: str, cache_visivel: dict, atividade_id: str = None
) -> None:
    """Confere e repara exatamente os cards que a interface marcou.

    Primeiro relê o cache canônico. Se o R2 já estiver vinculado ao anúncio,
    basta a revisão local atualizar a tela. Caso o mesmo anúncio ainda esteja
    sem URL permanente, reaplica somente o armazenamento das imagens.
    """
    try:
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "versao_forcamento": "V258",
                "etapa": "conferindo_relogios_visiveis",
                "aviso": "Conferindo no R2 as imagens que aparecem com relógio na tela.",
                "ultimo_heartbeat_em": _agora_iso(),
            })

        _visiveis = _encontrar_imagens_gads_pendentes_v257(cache_visivel)
        _ids_visiveis = {
            (str(_empresa), str((_ad or {}).get("id") or ""))
            for _empresa, _entry in _visiveis.items()
            for _ad in ((_entry or {}).get("data") or [])
        }
        _canonico = _carregar_checkpoints_gads_r2(user_id) or {}

        _alvo = {}
        for _empresa, _entry_vis in _visiveis.items():
            _entry_can = _canonico.get(_empresa) or {}
            _can_por_id = {
                str((_ad or {}).get("id") or ""): _ad
                for _ad in ((_entry_can or {}).get("data") or [])
            }
            _ads_alvo = []
            for _ad_vis in ((_entry_vis or {}).get("data") or []):
                _ad_id = str((_ad_vis or {}).get("id") or "")
                _ad_atual = _can_por_id.get(_ad_id) or _ad_vis
                if _imagem_gads_exibe_relogio_v258(_ad_atual):
                    _ads_alvo.append(_ad_atual)
            if _ads_alvo:
                _base = copy.deepcopy(_entry_can or _entry_vis or {})
                _base["data"] = _ads_alvo
                _alvo[_empresa] = _base

        _ja_estavam_no_r2 = max(0, len(_ids_visiveis) - sum(
            len((_entry or {}).get("data") or []) for _entry in _alvo.values()
        ))
        _stats = {"total": 0, "processadas": 0, "salvas": 0, "falhas": 0, "empresas": []}
        if _alvo:
            _cache_reparo = copy.deepcopy(_canonico)
            for _empresa, _entry_alvo in _alvo.items():
                if _empresa not in _cache_reparo:
                    _cache_reparo[_empresa] = copy.deepcopy(_entry_alvo)
            _cache_reparo, _stats = _forcar_armazenamento_imagens_gads_v257(
                user_id, _cache_reparo, atividade_id=atividade_id
            )

        _depois = _carregar_checkpoints_gads_r2(user_id) or {}
        _salvar_manifesto_gads_json_v261(
            user_id, _depois, motivo="reparo_imagens_com_relogio"
        )
        for _empresa_ocr_v260 in sorted(_visiveis.keys()):
            iniciar_ocr_pendente_background(user_id, str(_empresa_ocr_v260))
        _pendentes_depois = _encontrar_imagens_gads_pendentes_v257(_depois)
        _ids_pendentes_depois = {
            (str(_empresa), str((_ad or {}).get("id") or ""))
            for _empresa, _entry in _pendentes_depois.items()
            for _ad in ((_entry or {}).get("data") or [])
        }
        _restantes = len(_ids_visiveis & _ids_pendentes_depois)
        _det = {
            "versao_forcamento": "V258",
            "etapa": "reparo_dos_relogios_finalizado",
            "anuncios_verificados": len(_ids_visiveis),
            "ja_estavam_no_r2": _ja_estavam_no_r2,
            "imagens_salvas": int(_stats.get("salvas", 0) or 0),
            "anuncios_ainda_pendentes": _restantes,
            "ultimo_heartbeat_em": _agora_iso(),
        }
        if _restantes:
            _det["motivo"] = f"{_restantes} anúncio(s) ainda não puderam ter a imagem armazenada no R2."
            _det["aviso"] = _det["motivo"]
            if atividade_id:
                atualizar_atividade(atividade_id, "erro", _det)
        else:
            _det["aviso"] = (
                f"{len(_ids_visiveis)} anúncio(s) conferido(s): "
                f"{_ja_estavam_no_r2} já estava(m) no R2 e "
                f"{int(_stats.get('salvas', 0) or 0)} imagem(ns) foi(ram) armazenada(s)."
            )
            if atividade_id:
                atualizar_atividade(atividade_id, "concluido", _det)
        print(f"[GADS-R2-V258] reparo visual concluído detalhes={_det}", flush=True)
    except Exception as _exc:
        print(f"[GADS-R2-V258] reparo visual falhou: {_exc!r}", flush=True)
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {
                "versao_forcamento": "V258",
                "motivo": str(_exc),
                "ultimo_heartbeat_em": _agora_iso(),
            })


def _reconciliar_manifesto_gads_pos_login_v261(
    user_id: str, atividade_id: str = None
) -> None:
    """Cria/relê o manifesto e transforma diferenças em ações reais."""
    _acoes = []

    def _detalhes_empresas(_manifesto: dict, _em_verificacao: bool = False) -> dict:
        """Converte o manifesto em linhas legíveis no card da atividade."""
        _resultado = {}
        for _empresa_doc in ((_manifesto or {}).get("empresas") or []):
            _nome = str((_empresa_doc or {}).get("nome") or "Empresa sem nome")
            _ads = (_empresa_doc or {}).get("anuncios") or []
            _total = len(_ads)
            _midia_pendente = sum(
                1 for _ad in _ads if (_ad or {}).get("status_midia") == "pendente"
            )
            _midia_salva = sum(
                1 for _ad in _ads if (_ad or {}).get("status_midia") == "salva_r2"
            )
            _ocr_pendente = sum(
                1 for _ad in _ads
                if (_ad or {}).get("status_ocr") in ("pendente", "aguardando_midia")
            )
            _ocr_ok = sum(
                1 for _ad in _ads if (_ad or {}).get("status_ocr") == "concluido"
            )
            _cc_pendente = sum(
                1 for _ad in _ads if (_ad or {}).get("status_cc") == "pendente"
            )
            _cc_ok = sum(
                1 for _ad in _ads
                if (_ad or {}).get("status_cc") in (
                    "concluido", "sem_cc_confirmado", "erro_captura"
                )
            )
            _msg = (
                f"{_total} anúncio(s) · mídia: {_midia_salva} salva(s), "
                f"{_midia_pendente} pendente(s) · OCR: {_ocr_ok} concluído(s), "
                f"{_ocr_pendente} pendente(s) · CC: {_cc_ok} verificado(s), "
                f"{_cc_pendente} pendente(s)"
            )
            _resultado[_nome] = {
                "status": "rodando" if (
                    _em_verificacao or _midia_pendente or _ocr_pendente or _cc_pendente
                ) else "ok",
                "msg": _msg,
                "anuncios": _total,
                "midias_salvas": _midia_salva,
                "midias_pendentes": _midia_pendente,
                "ocr_concluidos": _ocr_ok,
                "ocr_pendentes": _ocr_pendente,
                "cc_verificados": _cc_ok,
                "cc_pendentes": _cc_pendente,
            }
        return _resultado

    def _publicar_empresas(_manifesto: dict, _etapa: str, _aviso: str,
                           _em_verificacao: bool = False) -> None:
        if not atividade_id:
            return
        _por_empresa = _detalhes_empresas(_manifesto, _em_verificacao)
        atualizar_atividade(atividade_id, "em_andamento", {
            "etapa": _etapa,
            "aviso": _aviso,
            "empresas": list(_por_empresa.keys()),
            "total": len(_por_empresa),
            "concluidas": sum(
                1 for _info in _por_empresa.values()
                if _info.get("status") == "ok"
            ),
            "por_empresa": _por_empresa,
            "ultimo_heartbeat_em": _agora_iso(),
        })
    try:
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "etapa": "lendo_manifesto",
                "aviso": "Verificando o controle geral dos anúncios após o login.",
                "ultimo_heartbeat_em": _agora_iso(),
            })

        _manifesto_antigo, _motivo_leitura = _ler_manifesto_gads_json_v261(user_id)
        _cache = None
        if _manifesto_antigo is None:
            _acoes.append("manifesto_criado")
            print(
                f"[GADS-MANIFEST-V261] inexistente; criando motivo={_motivo_leitura!r}",
                flush=True,
            )
        else:
            _acoes.append("manifesto_relido")
            _publicar_empresas(
                _manifesto_antigo,
                "analisando_empresas",
                "Manifesto encontrado. Conferindo mídia e OCR de cada empresa.",
                _em_verificacao=True,
            )

        _cache = _carregar_checkpoints_gads_r2(user_id) or {}
        _ok_inicial, _manifesto_inicial = _salvar_manifesto_gads_json_v261(
            user_id, _cache, motivo="reconstrucao_fonte_real_v273"
        )
        if _ok_inicial:
            _manifesto_antigo = _manifesto_inicial
            _publicar_empresas(
                _manifesto_inicial,
                "analisando_empresas",
                "Controle reconstruído. Conferindo mídia e OCR de cada empresa.",
                _em_verificacao=True,
            )
        _resumo_antigo = ((_manifesto_antigo or {}).get("resumo") or {})
        _qtd_pendentes_midia = int(_resumo_antigo.get("midia_pendente", 0) or 0)
        _pendentes_midia = (
            _encontrar_imagens_gads_pendentes_v257(_cache)
            if _cache is not None else {}
        )
        _qtd_pendentes_midia = sum(
            len((_entry or {}).get("data") or [])
            for _entry in _pendentes_midia.values()
        ) if _cache is not None else _qtd_pendentes_midia
        if _pendentes_midia:
            _acoes.append(f"migracao_iniciada:{_qtd_pendentes_midia}")
            if atividade_id:
                atualizar_atividade(atividade_id, "em_andamento", {
                    "etapa": "migrando_midias_pendentes",
                    "midias_pendentes": _qtd_pendentes_midia,
                    "aviso": (
                        f"{_qtd_pendentes_midia} anúncio(s) com imagem não migrada. "
                        "Armazenamento iniciado automaticamente."
                    ),
                    "ultimo_heartbeat_em": _agora_iso(),
                })
            _reparar_imagens_visiveis_com_relogio_v258(
                user_id, _cache, atividade_id=None
            )
            _cache = _carregar_checkpoints_gads_r2(user_id) or {}
            _ok_pos_midia, _manifesto_pos_midia = _salvar_manifesto_gads_json_v261(
                user_id, _cache, motivo="reconciliacao_midia_pos_login"
            )
            if _ok_pos_midia:
                _publicar_empresas(
                    _manifesto_pos_midia,
                    "verificando_ocr_por_empresa",
                    "Mídias conferidas. Verificando OCR pendente por empresa.",
                )

        _cache_cc = _cache or _cache_minimo_do_manifesto_v265(
            _manifesto_antigo or {}
        )
        _cc_iniciado = iniciar_verificacao_cc_youtube_automatica_v151(
            user_id,
            _cache_cc,
            intervalo_segundos=300,
            permitir_enfileirar=True,
        )
        if _cc_iniciado:
            _acoes.append("cc_youtube_enfileirado")

        _empresas_ocr = _empresas_com_ocr_pendente(user_id)
        _ocr_iniciados = []
        _ocr_nao_iniciados = []
        for _empresa in _empresas_ocr:
            _resultado_ocr = iniciar_ocr_pendente_background(
                user_id, _empresa, force=True
            ) or {"ok": False, "motivo": "sem_retorno"}
            if _resultado_ocr.get("ok"):
                _ocr_iniciados.append({
                    "empresa": _empresa,
                    "atividade_id": _resultado_ocr.get("atividade_id"),
                    "motivo": _resultado_ocr.get("motivo"),
                    "total": int(_resultado_ocr.get("total") or 0),
                })
            else:
                _ocr_nao_iniciados.append({
                    "empresa": _empresa,
                    "atividade_id": _resultado_ocr.get("atividade_id"),
                    "motivo": _resultado_ocr.get("motivo") or "não informado",
                })
        if _ocr_iniciados:
            _acoes.append(f"ocr_enfileirado:{len(_ocr_iniciados)}")
        if _ocr_nao_iniciados:
            _acoes.append(f"ocr_nao_iniciado:{len(_ocr_nao_iniciados)}")

        _cache_manifesto = _cache
        if _cache_manifesto is None:
            _cache_manifesto = _cache_minimo_do_manifesto_v265(
                _manifesto_antigo or {}
            )
        _ok_manifesto, _manifesto_novo = _salvar_manifesto_gads_json_v261(
            user_id, _cache_manifesto or {}, motivo="reconciliacao_pos_login"
        )
        _resumo = (_manifesto_novo.get("resumo") or {})
        _detalhes = {
            "etapa": "manifesto_reconciliado",
            "manifesto_existia": _manifesto_antigo is not None,
            "manifesto_salvo": bool(_ok_manifesto),
            "acoes": _acoes,
            "total_anuncios": int(_resumo.get("anuncios", 0) or 0),
            "midias_salvas": int(_resumo.get("midia_salva", 0) or 0),
            "midias_pendentes": int(_resumo.get("midia_pendente", 0) or 0),
            "ocr_concluidos": int(_resumo.get("ocr_concluido", 0) or 0),
            "ocr_pendentes": int(_resumo.get("ocr_pendente", 0) or 0),
            "cc_concluidos": int(_resumo.get("cc_concluido", 0) or 0),
            "cc_pendentes": int(_resumo.get("cc_pendente", 0) or 0),
            "atividade_cc_iniciada": bool(_cc_iniciado),
            "empresas_ocr_enfileiradas": _empresas_ocr,
            "atividades_ocr_iniciadas": _ocr_iniciados,
            "ocr_nao_iniciados": _ocr_nao_iniciados,
            "empresas": [
                str((_empresa or {}).get("nome") or "")
                for _empresa in (_manifesto_novo.get("empresas") or [])
            ],
            "por_empresa": _detalhes_empresas(_manifesto_novo),
            "ultimo_heartbeat_em": _agora_iso(),
        }
        _detalhes["total"] = len(_detalhes["por_empresa"])
        _detalhes["concluidas"] = _detalhes["total"]
        # Esta rotina roda automaticamente ao abrir/logar. Se ela apenas
        # conferiu o controle e não encontrou nada para processar, não deixe
        # uma notificação vazia no histórico. Mantemos o card somente quando
        # houve pendência, uma atividade foi disparada ou ocorreu erro.
        _teve_acao_relevante = bool(
            _qtd_pendentes_midia
            or _ocr_iniciados
            or _ocr_nao_iniciados
            or _cc_iniciado
        )
        if _ok_manifesto and not _ocr_nao_iniciados:
            _detalhes["aviso"] = (
                f"Controle geral atualizado: {_detalhes['total_anuncios']} anúncio(s), "
                f"{_detalhes['midias_pendentes']} mídia(s) pendente(s) e "
                f"{_detalhes['ocr_pendentes']} OCR(s) pendente(s). "
                f"{_detalhes['cc_pendentes']} CC(s) pendente(s). "
                f"{len(_ocr_iniciados)} atividade(s) de OCR e "
                f"{1 if _cc_iniciado else 0} atividade de CC iniciada(s)."
            )
            if atividade_id:
                if _teve_acao_relevante:
                    atualizar_atividade(atividade_id, "concluido", _detalhes)
                else:
                    excluir_atividade(atividade_id, user_id)
        elif _ok_manifesto and _ocr_nao_iniciados:
            _detalhes["motivo"] = (
                f"Foram encontrados OCRs pendentes, mas {len(_ocr_nao_iniciados)} "
                "empresa(s) não tiveram a atividade iniciada."
            )
            _detalhes["aviso"] = _detalhes["motivo"]
            if atividade_id:
                atualizar_atividade(atividade_id, "erro", _detalhes)
        else:
            _detalhes["motivo"] = str(_manifesto_novo.get("erro") or "Falha ao salvar o manifesto.")
            if atividade_id:
                atualizar_atividade(atividade_id, "erro", _detalhes)
    except Exception as _exc:
        print(f"[GADS-MANIFEST-V261] reconciliação pós-login falhou: {_exc!r}", flush=True)
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {
                "etapa": "reconciliacao_pos_login",
                "motivo": str(_exc),
                "acoes": _acoes,
                "ultimo_heartbeat_em": _agora_iso(),
            })


def iniciar_reconciliacao_manifesto_gads_pos_login_v261(
    user_id: str, origem: str = "pos_login"
) -> bool:
    """Abre a reconciliação do manifesto sem duplicar um processo ativo."""
    if not user_id:
        return False
    if _job_is_active("manifesto_gads_v261", user_id, "pos_login"):
        st.session_state["_manifesto_gads_ultima_solicitacao_epoch_v269"] = time.time()
        print(
            f"[GADS-MANIFEST-V269] manifesto já ativo; origem={origem}",
            flush=True,
        )
        return True
    st.session_state["_manifesto_gads_ultima_solicitacao_epoch_v269"] = time.time()
    _aviso_origem = (
        "Lendo ou criando o manifesto geral ao abrir a página do Google Ads."
        if origem == "abertura_pagina_google_ads"
        else "Lendo ou criando o manifesto geral após o login."
    )
    _atividade_id = criar_atividade(
        user_id,
        "verificacao_pendentes_gads",
        "Verificando controle geral dos anúncios do Google Ads",
        {
            "versao_manifesto": "V269",
            "origem_acionamento": origem,
            "aviso": _aviso_origem,
        },
    )
    _iniciou = _job_start_thread(
        "manifesto_gads_v261",
        user_id,
        "pos_login",
        _reconciliar_manifesto_gads_pos_login_v261,
        args=(user_id, _atividade_id),
        daemon=True,
        name="manifesto-google-ads-pos-login-v261",
    )
    if not _iniciou and _atividade_id:
        # Já existe uma verificação em andamento. O registro recém-criado não
        # representa trabalho adicional e só poluiria as Notificações.
        excluir_atividade(_atividade_id, user_id)
    return _iniciou

def verificar_e_migrar_pendentes(user_id: str) -> int:
    """Roda a varredura completa e dispara a migração pra tudo que ainda
    estiver com link original. Devolve quantos anúncios foram
    encontrados pendentes (0 = nada a fazer)."""
    try:
        ads_cache = _ler_blob_ci_dados_v291(user_id, "ads_cache", padrao={}) or {}
        pendentes = encontrar_ads_com_link_original(ads_cache)
        total_ads_pendentes = sum(len(e.get("data", [])) for e in pendentes.values())
        print(f"[MIGR-DEBUG] verificar_e_migrar_pendentes: {total_ads_pendentes} anúncio(s) pendente(s) em {list(pendentes.keys())}", flush=True)
        if pendentes:
            iniciar_migracao_midia_background(user_id, pendentes)
        return total_ads_pendentes
    except Exception as e:
        print(f"[MIGR-DEBUG] verificar_e_migrar_pendentes EXCEÇÃO: {e!r}", flush=True)
        return 0

def _verificar_e_migrar_pendentes_google_bg(user_id: str, atividade_id: str = None) -> int:
    """Corpo de verificar_e_migrar_pendentes_google, mas já recebendo o
    atividade_id criado ANTES de começar (ver
    iniciar_verificacao_pendentes_google_background) — assim o card
    aparece no sino como "em andamento" desde o primeiro instante, em
    vez de só surgir (ou não) depois que a varredura já decidiu se tem
    algo pra migrar. Sem isso, enquanto uma imagem ficava com o selo de
    relógio (link ainda não permanente) e sem OCR, não existia NENHUM
    sinal no sino explicando o porquê — parecia que nada estava
    acontecendo."""
    try:
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "etapa": "lendo_cache_google",
                "etapa_atual": 2,
                "total_etapas": 3,
                "aviso": (
                    "Etapa 2 de 3: lendo os anúncios salvos e procurando "
                    "imagens que ainda exibem o relógio."
                ),
                "ultimo_heartbeat_em": _agora_iso(),
            })
        try:
            gads_cache = _carregar_checkpoints_gads_r2(user_id) or {}
            _fonte_verificacao = "r2_por_empresa"
        except Exception as _exc_cache_r2:
            print(f"[MIGR-DEBUG] V248 fallback gads_cache: {_exc_cache_r2!r}", flush=True)
            res = supabase.table("ci_dados").select("gads_cache").eq("user_id", user_id).execute()
            gads_cache = (res.data[0].get("gads_cache") or {}) if res.data else {}
            _fonte_verificacao = "gads_cache_legado"
        if _fonte_verificacao == "r2_por_empresa":
            gads_cache, _reconectadas_v256 = _reconectar_gads_r2_com_midias_salvas_v256(
                user_id, gads_cache, atividade_id=atividade_id
            )
            if _reconectadas_v256:
                _fonte_verificacao = "r2_por_empresa_reconciliado"
        _pendentes_antes = _encontrar_imagens_gads_pendentes_v257(gads_cache)
        _total_ads_antes = sum(len(e.get("data", [])) for e in _pendentes_antes.values())
        print(
            f"[GADS-R2-V257] imagens pendentes antes={_total_ads_antes} "
            f"empresas={list(_pendentes_antes.keys())}",
            flush=True,
        )
        _stats_v257 = {"total": 0, "processadas": 0, "salvas": 0, "falhas": 0, "empresas": []}
        if _pendentes_antes:
            gads_cache, _stats_v257 = _forcar_armazenamento_imagens_gads_v257(
                user_id, gads_cache, atividade_id=atividade_id
            )
        _pendentes_depois = _encontrar_imagens_gads_pendentes_v257(gads_cache)
        _total_ads_depois = sum(len(e.get("data", [])) for e in _pendentes_depois.values())

        if atividade_id:
            _detalhes_finais_v257 = {
                "versao_forcamento": "V257",
                "fonte_verificacao": _fonte_verificacao,
                "etapa": "armazenamento_finalizado",
                "etapa_atual": 3,
                "total_etapas": 3,
                "anuncios_pendentes_antes": _total_ads_antes,
                "anuncios_pendentes_depois": _total_ads_depois,
                **_stats_v257,
                "ultimo_heartbeat_em": _agora_iso(),
            }
            if _total_ads_depois:
                _detalhes_finais_v257.update({
                    "aviso": (
                        f"{_stats_v257.get('salvas', 0)} imagem(ns) salva(s). "
                        f"{_total_ads_depois} anúncio(s) ainda têm imagem pendente; "
                        "as URLs com falha respeitarão o limite de tentativas."
                    ),
                    "motivo": "Algumas imagens ainda não puderam ser armazenadas.",
                })
                atualizar_atividade(atividade_id, "erro", _detalhes_finais_v257)
            else:
                _detalhes_finais_v257["aviso"] = (
                    f"Armazenamento concluído: {_stats_v257.get('salvas', 0)} imagem(ns) "
                    "salva(s) e nenhum relógio de imagem pendente. O OCR foi acionado."
                )
                atualizar_atividade(atividade_id, "concluido", _detalhes_finais_v257)
        print(
            f"[GADS-R2-V257] imagens pendentes depois={_total_ads_depois} stats={_stats_v257}",
            flush=True,
        )
        return _total_ads_depois
    except Exception as e:
        print(f"[MIGR-DEBUG] verificar_e_migrar_pendentes_google EXCEÇÃO: {e!r}", flush=True)
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})
        return 0

def verificar_e_migrar_pendentes_google(user_id: str) -> int:
    """Equivalente a verificar_e_migrar_pendentes, mas pro Google Ads —
    lê `gads_cache` (não `ads_cache`) e passa plataforma="Google Ads"
    pra migração, pra não misturar com a atividade de Meta Ads de uma
    empresa com o mesmo nome nas duas fontes.

    Existia um bug real aqui: a varredura de segurança da aba de Google
    Ads chamava por engano a função do Meta (que só olha `ads_cache`),
    então imagens do Google que nunca foram migradas na primeira
    tentativa — e por isso nunca caíram em `midias_falhas` — ficavam
    órfãs pra sempre: nem a migração pontual da coleta pegava (já tinha
    passado), nem a retentativa (só olha o que já está em
    midias_falhas), nem essa varredura (olhava a tabela errada).

    Mantida sem atividade própria (chamada direta, sem card no sino) —
    use iniciar_verificacao_pendentes_google_background pra rodar com
    card visível desde o início."""
    return _verificar_e_migrar_pendentes_google_bg(user_id, atividade_id=None)

_MIN_MINUTOS_ENTRE_VERIFICACOES_PENDENTES_GADS = 15

def _verificar_pendentes_google_apos_janela_coleta_v205(user_id: str, atividade_id: str):
    """Adia a manutenção automática para dar prioridade real à coleta.

    Ao abrir a página, o usuário normalmente clica em Buscar/Atualizar nos
    primeiros instantes. Antes, a migração antiga começava imediatamente e
    ocupava CPU/rede antes desse clique. Agora ela aguarda uma janela curta;
    se uma coleta começar, espera a coleta terminar e só então faz a varredura.
    """
    def _bloqueios_coleta_atuais():
        _rotulos = {
            "coleta_ads_google": "coleta do Google Ads",
            "coleta_ads": "coleta do Meta Ads",
            "coleta_redes": "coleta de redes sociais",
            "sincronizar_gads_outbox": "confirmação dos dados coletados",
        }
        _ativos = [
            _rotulos[_tipo] for _tipo in _rotulos
            if _job_any_active(_tipo, user_id)
        ]
        if _coleta_prioritaria_local_ativa(user_id) and not _ativos:
            _ativos.append("finalização protegida de uma coleta")
        return _ativos

    _bloqueios_iniciais_v250 = _bloqueios_coleta_atuais()
    _pendencias_confirmadas_v250 = False
    if not _bloqueios_iniciais_v250:
        try:
            _cache_inicio_v250 = _carregar_checkpoints_gads_r2(user_id) or {}
            _pendencias_confirmadas_v250 = bool(
                encontrar_ads_com_link_original(
                    _cache_inicio_v250, incluir_foto_perfil=False
                )
            )
        except Exception as _exc_v250:
            print(f"[MIGR-DEBUG] V250 pré-checagem falhou: {_exc_v250!r}", flush=True)
    if _pendencias_confirmadas_v250:
        atualizar_atividade(atividade_id, "em_andamento", {
            "aguardando_coleta_prioritaria": False,
            "etapa": "pendencias_confirmadas",
            "etapa_atual": 2,
            "total_etapas": 3,
            "aviso": (
                "Imagens com relógio já confirmadas no cache. "
                "A verificação começou imediatamente, sem a espera de 120 segundos."
            ),
            "ultimo_heartbeat_em": _agora_iso(),
        })
        print("[MIGR-DEBUG] V250 pula janela: imagens com relógio confirmadas", flush=True)

    for _passo in range(0 if _pendencias_confirmadas_v250 else 24):  # 120 segundos, em passos de 5s
        _bloqueios = _bloqueios_coleta_atuais()
        _restantes = max(0, 120 - (_passo * 5))
        if _bloqueios:
            atualizar_atividade(atividade_id, "em_andamento", {
                "aguardando_coleta_prioritaria": True,
                "etapa": "aguardando_coleta",
                "etapa_atual": 1,
                "total_etapas": 3,
                "bloqueios": _bloqueios,
                "aviso": (
                    "Etapa 1 de 3: aguardando terminar "
                    f"{', '.join(_bloqueios)}. Depois serão verificadas as imagens "
                    "com relógio e iniciado o salvamento permanente."
                ),
                "ultimo_heartbeat_em": _agora_iso(),
            })
            break
        if _passo == 0 or _passo % 2 == 0:
            atualizar_atividade(atividade_id, "em_andamento", {
                "aguardando_coleta_prioritaria": True,
                "etapa": "janela_antes_da_manutencao",
                "etapa_atual": 1,
                "total_etapas": 3,
                "segundos_restantes": _restantes,
                "aviso": (
                    f"Etapa 1 de 3: nenhuma coleta ativa. A verificação das imagens "
                    f"com relógio começará em até {_restantes} segundos; essa janela "
                    "evita que a manutenção atrapalhe uma nova coleta."
                ),
                "ultimo_heartbeat_em": _agora_iso(),
            })
        time.sleep(5)

    _ultimo_texto_bloqueio = None
    while True:
        _bloqueios = _bloqueios_coleta_atuais()
        if not _bloqueios:
            break
        _texto_bloqueio = ", ".join(_bloqueios)
        if _texto_bloqueio != _ultimo_texto_bloqueio:
            atualizar_atividade(atividade_id, "em_andamento", {
                "aguardando_coleta_prioritaria": True,
                "etapa": "aguardando_coleta",
                "etapa_atual": 1,
                "total_etapas": 3,
                "bloqueios": _bloqueios,
                "aviso": (
                    f"Etapa 1 de 3: aguardando terminar {_texto_bloqueio}. "
                    "A verificação continuará automaticamente logo depois."
                ),
                "ultimo_heartbeat_em": _agora_iso(),
            })
            _ultimo_texto_bloqueio = _texto_bloqueio
        time.sleep(5)

    atualizar_atividade(atividade_id, "em_andamento", {
        "aguardando_coleta_prioritaria": False,
        "etapa": "iniciando_varredura",
        "etapa_atual": 2,
        "total_etapas": 3,
        "aviso": "Etapa 2 de 3: iniciando a verificação das imagens que ainda exibem o relógio.",
        "ultimo_heartbeat_em": _agora_iso(),
    })
    return _verificar_e_migrar_pendentes_google_bg(user_id, atividade_id)

def iniciar_verificacao_pendentes_google_background(user_id: str):
    """Cria a atividade no sino ANTES de disparar a thread — o card
    aparece imediatamente como "em andamento" (mesmo padrão de
    iniciar_retentativa_midias_background), pra o usuário ver que a
    checagem está rolando enquanto o selo de relógio/ausência de OCR
    ainda aparece no card, em vez de ficar sem nenhuma explicação até
    (ou a menos que) a varredura ache algo pra migrar.

    O flag `_verificacao_pendentes_feita_google` na sessão só evita
    repetir isso a cada RERUN da mesma aba — mas cada F5/nova aba/nova
    sessão zera a sessão e essa checagem rodava nela de novo, criando
    um card novo no sino a cada recarregada da página. Por isso, além
    do flag de sessão, essa função também confere no BANCO se já rodou
    uma verificação recente (< _MIN_MINUTOS_ENTRE_VERIFICACOES_PENDENTES_GADS
    atrás) antes de criar outro card — assim, dar refresh na página
    repetidas vezes num curto intervalo não enche o sino de cards
    idênticos de "Verificando anúncios do Google Ads pendentes de
    migração"."""
    try:
        _res_ultima = (
            supabase.table("atividades")
            .select("criado_em,status")
            .eq("user_id", user_id)
            .eq("tipo", "verificacao_pendentes_gads")
            .order("criado_em", desc=True)
            .limit(1)
            .execute()
        )
        if _res_ultima.data:
            _minutos_desde = _segundos_desde(_res_ultima.data[0]["criado_em"]) / 60
            if _minutos_desde < _MIN_MINUTOS_ENTRE_VERIFICACOES_PENDENTES_GADS:
                _status_ultima = str(_res_ultima.data[0].get("status") or "")
                _detalhes_ultima = _res_ultima.data[0].get("detalhes") or {}
                if _detalhes_ultima.get("versao_forcamento") == "V257":
                    print(
                        f"[GADS-R2-V257] throttle respeitado minutos={_minutos_desde:.1f}",
                        flush=True,
                    )
                    return
                if _status_ultima in ("pendente", "em_andamento") and _minutos_desde < 5:
                    return
                try:
                    _cache_canonico_agora = _carregar_checkpoints_gads_r2(user_id) or {}
                    _ainda_tem_relogios = bool(
                        encontrar_ads_com_link_original(
                            _cache_canonico_agora, incluir_foto_perfil=False
                        )
                    )
                except Exception as _exc_recheck:
                    print(
                        f"[MIGR-DEBUG] V248 não confirmou relógios no throttle: {_exc_recheck!r}",
                        flush=True,
                    )
                    _ainda_tem_relogios = False
                if not _ainda_tem_relogios:
                    return
                print(
                    "[MIGR-DEBUG] V248 ignora throttle: verificação recente terminou, "
                    "mas ainda há imagens com relógio no cache canônico",
                    flush=True,
                )
    except Exception:
        pass  # sem confirmar a última verificação, segue e cria mesmo assim — não trava a funcionalidade por causa do throttle
    atividade_id = criar_atividade(
        user_id, "verificacao_pendentes_gads",
        "Verificando anúncios do Google Ads pendentes de migração", {}
    )
    threading.Thread(
        target=_verificar_pendentes_google_apos_janela_coleta_v205,
        args=(user_id, atividade_id),
        daemon=True,
        name="verificacao-gads-adiada-v205",
    ).start()

def _verificar_e_gerar_ocr_pendentes_google_bg(user_id: str, atividade_id: str = None) -> int:
    """Equivalente a _verificar_e_migrar_pendentes_google_bg, mas pra OCR:
    varre TODAS as empresas do usuário (não só a que acabou de coletar/
    migrar) procurando imagens do Google Ads já migradas pro R2 mas ainda
    sem texto extraído, e dispara `iniciar_ocr_pendente_background` pra
    cada uma. Usa `_empresas_com_ocr_pendente`, que já filtra
    `tipo == "imagem"` — anúncios em vídeo nunca entram nessa contagem,
    porque o card de vídeo usa o próprio frame do `<video>` como thumb
    (ver `encontrar_ads_com_link_original`), não faz sentido rodar OCR
    neles.

    Sem essa varredura, uma imagem que ficasse sem OCR por qualquer
    motivo (falha silenciosa na fila, migração antiga anterior a essa
    funcionalidade existir, etc.) ficava órfã pra sempre: a fila de OCR
    só era acionada logo após uma migração pontual (ver
    `iniciar_ocr_pendente_background` chamada em `_migrar_midia_background`
    e no botão manual da aba de configurações) — nunca por uma checagem
    de segurança geral, como já existia pros links permanentes."""
    try:
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "aviso": "Verificando no banco quais imagens já foram salvas e ainda estão sem OCR.",
                "ultimo_heartbeat_em": _agora_iso(),
            })
        empresas_pendentes = _empresas_com_ocr_pendente(user_id)
        print(f"[OCR-DEBUG] verificar_e_gerar_ocr_pendentes_google: {len(empresas_pendentes)} empresa(s) com OCR pendente -> {empresas_pendentes}", flush=True)
        for empresa in empresas_pendentes:
            iniciar_ocr_pendente_background(user_id, empresa)
        if atividade_id:
            if empresas_pendentes:
                atualizar_atividade(atividade_id, "concluido", {
                    "empresas": empresas_pendentes,
                    "aviso": (
                        f"{len(empresas_pendentes)} empresa(s) com imagens do Google Ads "
                        f"sem texto extraído — OCR enviado pra rodar agora "
                        f"(acompanhe abaixo)."
                    ),
                })
            else:
                atualizar_atividade(atividade_id, "concluido", {
                    "aviso": "Nenhuma imagem do Google Ads pendente de OCR — tudo já tem texto extraído.",
                })
        return len(empresas_pendentes)
    except Exception as e:
        print(f"[OCR-DEBUG] verificar_e_gerar_ocr_pendentes_google EXCEÇÃO: {e!r}", flush=True)
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})
        return 0

_MIN_MINUTOS_ENTRE_VERIFICACOES_OCR_PENDENTE_GADS = 15

def iniciar_verificacao_ocr_pendente_google_background(user_id: str):
    """Mesmo padrão de `iniciar_verificacao_pendentes_google_background`
    (throttle por sessão + por banco, card no sino desde o início), mas
    pra disparar a checagem de segurança de OCR em vez de migração de
    link. As duas rodam lado a lado, de forma independente, na mesma
    aba de Google Ads."""
    try:
        _res_ultima = (
            supabase.table("atividades")
            .select("criado_em")
            .eq("user_id", user_id)
            .eq("tipo", "verificacao_ocr_pendente_gads")
            .order("criado_em", desc=True)
            .limit(1)
            .execute()
        )
        if _res_ultima.data:
            _minutos_desde = _segundos_desde(_res_ultima.data[0]["criado_em"]) / 60
            if _minutos_desde < _MIN_MINUTOS_ENTRE_VERIFICACOES_OCR_PENDENTE_GADS:
                _status_ultima = str(_res_ultima.data[0].get("status") or "")
                if _status_ultima in ("pendente", "em_andamento") and _minutos_desde < 5:
                    return
                if not _empresas_com_ocr_pendente(user_id):
                    return
                print(
                    "[OCR-DEBUG] V248 ignora throttle: surgiram imagens sem OCR "
                    "depois da verificação anterior",
                    flush=True,
                )
    except Exception:
        pass  # sem confirmar a última verificação, segue e cria mesmo assim — não trava a funcionalidade por causa do throttle
    atividade_id = criar_atividade(
        user_id, "verificacao_ocr_pendente_gads",
        "Verificando anúncios do Google Ads pendentes de OCR", {}
    )
    threading.Thread(
        target=_verificar_e_gerar_ocr_pendentes_google_bg,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()

def _reparar_links_quebrados_background(user_id: str, atividade_id: str):
    """As varreduras normais só olham se a URL É do R2 (pelo prefixo) —
    não confirmam se o arquivo realmente existe lá. Se um objeto sumir
    do bucket por qualquer motivo (ex: uma corrida durante o
    reprocessamento), essas varreduras nunca detectam, porque pra elas
    já "está tudo certo". Essa função verifica de verdade (HEAD request)
    e, pro que estiver quebrado, busca o link original em `midias.
    url_origem` pra tentar migrar de novo."""
    try:
        ads_cache = _ler_blob_ci_dados_v291(user_id, "ads_cache", padrao={}) or {}

        res_midias = supabase.table("midias").select("url_cdn, url_origem").eq("user_id", user_id).execute()
        mapa_origem = {m["url_cdn"]: m["url_origem"] for m in (res_midias.data or []) if m.get("url_cdn")}

        verificados = 0
        quebrados = 0
        reparar = {}

        for empresa, entry in ads_cache.items():
            ads_para_reparar = []
            for ad in entry.get("data", []) or []:
                precisa_reparar = False
                ad_copia = dict(ad)
                for campo in ("images", "videos"):
                    urls = list(ad.get(campo) or [])
                    for i, u in enumerate(urls):
                        if not (u and R2_PUBLIC_BASE and u.startswith(R2_PUBLIC_BASE)):
                            continue
                        verificados += 1
                        try:
                            ok = _http_head(u, timeout=5).status_code == 200
                        except Exception:
                            ok = False
                        if not ok:
                            quebrados += 1
                            origem = mapa_origem.get(u)
                            if origem:
                                urls[i] = origem  # volta pro link original, pra tentar migrar de novo
                                precisa_reparar = True
                    ad_copia[campo] = urls

                _foto = ad.get("page_profile_picture")
                if _foto and R2_PUBLIC_BASE and _foto.startswith(R2_PUBLIC_BASE):
                    verificados += 1
                    try:
                        ok_foto = _http_head(_foto, timeout=5).status_code == 200
                    except Exception:
                        ok_foto = False
                    if not ok_foto:
                        quebrados += 1
                        origem_foto = mapa_origem.get(_foto)
                        if origem_foto:
                            ad_copia["page_profile_picture"] = origem_foto
                            precisa_reparar = True
                if precisa_reparar:
                    ads_para_reparar.append(ad_copia)
            if ads_para_reparar:
                reparar[empresa] = {**entry, "data": ads_para_reparar}

        if reparar:
            iniciar_migracao_midia_background(user_id, reparar)

        atualizar_atividade(atividade_id, "concluido", {
            "verificados": verificados,
            "quebrados": quebrados,
        })
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def iniciar_reparo_links_quebrados(user_id: str):
    """Confirma de verdade (não só pelo prefixo da URL) se as mídias já
    marcadas como salvas no R2 ainda existem, e repara o que sumiu."""
    atividade_id = criar_atividade(
        user_id, "reparo_links", "Verificando se os anúncios salvos ainda estão acessíveis", {}
    )
    threading.Thread(
        target=_reparar_links_quebrados_background,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()

def _resetar_falhas_midia_empresa(user_id: str, empresa: str) -> int:
    """Apaga os registros de midias_falhas desta empresa — zera o contador
    de tentativas, dando uma chance nova de download pras URLs que já
    bateram no teto de MAX_TENTATIVAS_MIDIA (ver o early-return em
    baixar_e_persistir_midia, que devolve a URL original sem nem tentar
    baixar quando tentativas >= teto).

    Só é chamada no clique MANUAL de "Refazer" (nunca no retry automático
    — ver retentar_migracoes_travadas_automaticamente): um clique
    explícito é o usuário pedindo pra tentar de novo mesmo sabendo que já
    falhou várias vezes, o que faz sentido quando a causa da falha era
    passageira (R2 fora do ar, rede, rate limit) e não o link em si.
    Resetar automaticamente, sem esse pedido explícito, faria a
    varredura automática cair de novo no loop infinito que o teto existe
    pra evitar. Devolve quantas linhas foram removidas."""
    try:
        res = (
            supabase.table("midias_falhas")
            .delete()
            .eq("user_id", user_id)
            .eq("empresa", empresa)
            .execute()
        )
        return len(res.data or [])
    except Exception:
        return 0

def _resetar_falhas_midia_usuario(user_id: str) -> int:
    """Igual a `_resetar_falhas_midia_empresa`, mas pra TODAS as empresas
    do usuário de uma vez — usado pelo "Refazer" da atividade
    `retentativa_midia`, que não é por empresa (ela varre `midias_falhas`
    do usuário inteiro). Sem isso, mídias que já bateram no teto de
    MAX_TENTATIVAS_MIDIA ficam excluídas da consulta pra sempre (ver
    _tentar_novamente_midias_background), e a atividade reporta "nenhuma
    mídia pendente de retentativa" mesmo com anúncios do Google ainda sem
    link permanente no R2 — o clique manual é o usuário pedindo pra
    tentar de novo mesmo sabendo que já esgotou as tentativas automáticas."""
    try:
        res = (
            supabase.table("midias_falhas")
            .delete()
            .eq("user_id", user_id)
            .execute()
        )
        return len(res.data or [])
    except Exception:
        return 0

def refazer_retentativa_midia(user_id: str, atividade_id: str) -> bool:
    """Refazer pra atividades `retentativa_midia`: zera o teto de
    tentativas de todas as mídias falhas do usuário e roda a retentativa
    de novo, reaproveitando a MESMA atividade (mesmo padrão de
    refazer_migracao_midia)."""
    try:
        _resetar_falhas_midia_usuario(user_id)
        atualizar_atividade(atividade_id, "em_andamento", {})
        threading.Thread(
            target=_tentar_novamente_midias_background,
            args=(user_id, atividade_id),
            daemon=True,
        ).start()
        return True
    except Exception:
        return False

def _criar_backup_antes_de_refazer_migracao(
    user_id: str, atividade_id: str, empresa: str, plataforma: str,
    entry: dict,
) -> dict:
    """Persiste um snapshot dos anúncios que a migração pode alterar.

    O snapshot é gravado na própria atividade ANTES de iniciar o worker. Se
    essa gravação falhar, o reprocessamento é bloqueado: nunca alteramos dados
    sem antes garantir um caminho de volta.
    """
    detalhes_atividade = {}
    try:
        _r = (
            supabase.table("atividades").select("detalhes")
            .eq("id", atividade_id).eq("user_id", user_id).limit(1).execute()
        )
        detalhes_atividade = ((_r.data or [{}])[0].get("detalhes") or {})
    except Exception:
        detalhes_atividade = {}

    ids_com_erro = {
        str(_x.get("id")) for _x in (detalhes_atividade.get("anuncios_com_erro") or [])
        if isinstance(_x, dict) and _x.get("id")
    }

    def _pode_ser_alterado(ad: dict) -> bool:
        ad_id = str(ad.get("id") or "")
        if ad_id and ad_id in ids_com_erro:
            return True
        urls = list(ad.get("images") or []) + list(ad.get("videos") or [])
        return any(_u and (not R2_PUBLIC_BASE or not str(_u).startswith(R2_PUBLIC_BASE)) for _u in urls)

    anuncios_backup = [dict(_ad) for _ad in (entry.get("data") or []) if _pode_ser_alterado(_ad)]
    if not anuncios_backup:
        return {}

    backup = {
        "empresa": empresa,
        "plataforma": plataforma,
        "criado_em": _agora_iso(),
        "desfeito": False,
        "anuncios": anuncios_backup,
        "total": len(anuncios_backup),
    }
    novos_detalhes = dict(detalhes_atividade)
    novos_detalhes["backup_desfazer"] = backup
    novos_detalhes["aviso_backup"] = (
        f"Backup de {len(anuncios_backup)} anúncio(s) criado antes do reprocessamento."
    )
    try:
        _supabase_resiliente(
            lambda: supabase.table("atividades").update({"detalhes": novos_detalhes})
                    .eq("id", atividade_id).eq("user_id", user_id).execute(),
            operacao="salvar_backup_antes_refazer",
            tentativas=5,
            backoff=(1, 2, 4, 8, 15),
        )
    except Exception:
        return {}
    _backups_desfazer_atividade[str(atividade_id)] = backup
    return backup

def desfazer_reprocessamento_anuncios(user_id: str, atividade: dict) -> tuple:
    """Restaura, por ID, somente os anúncios salvos antes desta tentativa."""
    atividade_id = atividade.get("id")
    detalhes = dict(atividade.get("detalhes") or {})
    backup = dict(detalhes.get("backup_desfazer") or {})
    anuncios = backup.get("anuncios") or []
    por_empresa_backup = backup.get("por_empresa") or {}
    if not atividade_id or (not anuncios and not por_empresa_backup) or backup.get("desfeito"):
        return False, "Não existe backup disponível para esta atividade."

    plataforma = backup.get("plataforma") or detalhes.get("plataforma") or "Meta Ads"
    empresa = backup.get("empresa") or detalhes.get("empresa")
    lotes_restaurar = por_empresa_backup or ({empresa: anuncios} if empresa else {})
    total_restaurado = 0
    try:
        for _empresa_undo, _ads_undo in lotes_restaurar.items():
            atualizacoes = {str(_ad.get("id")): _ad for _ad in (_ads_undo or []) if _ad.get("id")}
            if not atualizacoes:
                continue
            supabase.rpc(_rpc_atualizar_cache(plataforma), {
                "p_user_id": user_id,
                "p_empresa": _empresa_undo,
                "p_atualizacoes": atualizacoes,
            }).execute()
            total_restaurado += len(atualizacoes)
        if not total_restaurado:
            return False, "O backup não contém empresa e IDs válidos."
        backup["desfeito"] = True
        backup["desfeito_em"] = _agora_iso()
        detalhes["backup_desfazer"] = backup
        detalhes["alteracoes_desfeitas"] = True
        detalhes["aviso"] = (
            f"Alterações desfeitas: {total_restaurado} anúncio(s) restaurado(s) "
            f"para o estado anterior ao reprocessamento."
        )
        _backups_desfazer_atividade[str(atividade_id)] = backup
        atualizar_atividade(atividade_id, "concluido", detalhes)
        return True, detalhes["aviso"]
    except Exception as exc:
        return False, f"Não foi possível restaurar o backup: {exc}"

def _ids_gads_incompletos_dos_detalhes(detalhes: dict) -> dict:
    """Aceita o formato V211 e também notificações antigas (texto com IDs)."""
    estruturado = detalhes.get("incompletos_ids_por_empresa") or {}
    if estruturado:
        return {str(k): [str(x) for x in (v or [])] for k, v in estruturado.items() if v}
    por_empresa_backup = ((detalhes.get("backup_desfazer") or {}).get("por_empresa") or {})
    if por_empresa_backup:
        convertido_backup = {}
        for empresa, anuncios in por_empresa_backup.items():
            ids = [str(ad.get("id")) for ad in (anuncios or []) if isinstance(ad, dict) and ad.get("id")]
            if ids:
                convertido_backup[str(empresa)] = ids
        if convertido_backup:
            return convertido_backup
    import re as _re_ids_gads
    convertido = {}
    for empresa, mensagem in (detalhes.get("incompletos") or {}).items():
        ids = _re_ids_gads.findall(r"\bCR\d+\b", str(mensagem or ""), flags=_re_ids_gads.I)
        if ids:
            convertido[str(empresa)] = ids
    return convertido

def garantir_atividade_gads_incompletos(user_id: str) -> str:
    """Cria a fila de recuperação quando o cache tem erro sem notificação.

    É idempotente: se já existir uma atividade aberta/erro com o mesmo
    conjunto empresa+ID, não cria outra. Isso também recupera anúncios
    incompletos de coletas feitas antes da V211.
    """
    if not user_id:
        return ""
    try:
        _cache = _carregar_checkpoints_gads_r2(user_id)
        _ids_por_empresa = {}
        for _empresa, _entry in _cache.items():
            _ids = []
            for _ad in ((_entry or {}).get("data") or []):
                if not isinstance(_ad, dict) or not _ad.get("id"):
                    continue
                _tem_midia = bool(
                    (_ad.get("images") or [])
                    or (_ad.get("images_b64") or [])
                    or (_ad.get("videos") or [])
                    or (_ad.get("origem_texto") == "html_google" and _gads_html_estruturado_valido(_ad.get("ocr_estruturado")))
                )
                if not _tem_midia:
                    _ids.append(str(_ad.get("id")))
            if _ids:
                _ids_por_empresa[str(_empresa)] = sorted(set(_ids))
        if not _ids_por_empresa:
            return ""

        _r_ativ = (
            supabase.table("atividades")
            .select("id,status,detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "coleta_ads_google")
            .order("criado_em", desc=True)
            .limit(100)
            .execute()
        )
        _atividades = _r_ativ.data or []
        _usadas_na_conversao = set()
        _ids_resultado = []

        def _payload_empresa(empresa: str, ids: list) -> tuple:
            total = len(ids)
            msg = (
                f"{total} anúncio(s) sem mídia validada; é necessário coletar novamente. "
                f"IDs: {', '.join(ids)}"
            )
            detalhes = {
                "empresa": empresa,
                "empresas": [empresa],
                "plataforma": "Google Ads",
                "coletadas": [],
                "com_erro": {empresa: msg},
                "incompletos": {empresa: msg},
                "incompletos_ids_por_empresa": {empresa: ids},
                "anuncios_com_erro": [
                    {"id": ad_id, "titulo": f"{empresa} · anúncio sem mídia validada"}
                    for ad_id in ids
                ],
                "total_anuncios_com_erro": total,
                "por_empresa": {empresa: {"status": "erro", "msg": msg}},
                "motivo": f"{total} anúncio(s) do Google Ads de {empresa} precisam ser refeitos.",
                "gerada_por_varredura": True,
                "separada_por_empresa": True,
            }
            titulo = f"{empresa} · {total} anúncio(s) do Google Ads para refazer"
            return titulo, detalhes

        for empresa, ids in _ids_por_empresa.items():
            assinatura_empresa = {(empresa, ad_id) for ad_id in ids}
            atividade_existente = None
            atividade_agrupada = None

            atividade_ativa_empresa = None
            for ativ in _atividades:
                if ativ.get("status") not in ("pendente", "em_andamento"):
                    continue
                det_ativa = ativ.get("detalhes") or {}
                empresas_ativas = {str(x) for x in (det_ativa.get("empresas") or []) if x}
                if det_ativa.get("empresa"):
                    empresas_ativas.add(str(det_ativa.get("empresa")))
                backup_ativa = det_ativa.get("backup_desfazer") or {}
                empresas_ativas.update(str(x) for x in (backup_ativa.get("por_empresa") or {}).keys())
                if backup_ativa.get("empresa"):
                    empresas_ativas.add(str(backup_ativa.get("empresa")))
                ids_ativos = _ids_gads_incompletos_dos_detalhes(det_ativa)
                empresas_ativas.update(ids_ativos.keys())
                if empresa in empresas_ativas:
                    atividade_ativa_empresa = ativ
                    break

            if atividade_ativa_empresa:
                for duplicada in _atividades:
                    if str(duplicada.get("id")) == str(atividade_ativa_empresa.get("id")):
                        continue
                    det_duplicada = duplicada.get("detalhes") or {}
                    if duplicada.get("status") != "erro" or not det_duplicada.get("gerada_por_varredura"):
                        continue
                    empresas_duplicada = set(_ids_gads_incompletos_dos_detalhes(det_duplicada).keys())
                    if empresa not in empresas_duplicada:
                        continue
                    id_duplicada = duplicada.get("id")
                    _supabase_resiliente(
                        lambda id_excluir=id_duplicada: supabase.table("atividades").delete()
                            .eq("id", id_excluir).eq("user_id", user_id).execute(),
                        operacao="remover_atividade_gads_duplicada", tentativas=4,
                    )
                _ids_resultado.append(str(atividade_ativa_empresa.get("id") or ""))
                continue

            for ativ in _atividades:
                if ativ.get("status") not in ("pendente", "em_andamento", "erro"):
                    continue
                existentes = _ids_gads_incompletos_dos_detalhes(ativ.get("detalhes") or {})
                assinatura_existente = {
                    (emp_exist, ad_id)
                    for emp_exist, ids_exist in existentes.items()
                    for ad_id in ids_exist
                }
                if assinatura_existente == assinatura_empresa:
                    atividade_existente = ativ
                    break
                if (
                    assinatura_empresa.issubset(assinatura_existente)
                    and len(existentes) > 1
                    and (ativ.get("detalhes") or {}).get("gerada_por_varredura")
                    and str(ativ.get("id")) not in _usadas_na_conversao
                ):
                    atividade_agrupada = ativ

            if atividade_existente:
                _ids_resultado.append(str(atividade_existente.get("id") or ""))
                continue

            titulo, detalhes = _payload_empresa(empresa, ids)
            if atividade_agrupada:
                ativ_id = atividade_agrupada.get("id")
                _supabase_resiliente(
                    lambda: supabase.table("atividades").update({
                        "titulo": titulo, "detalhes": detalhes, "status": "erro"
                    }).eq("id", ativ_id).eq("user_id", user_id).execute(),
                    operacao="separar_atividade_gads_por_empresa", tentativas=4,
                )
                _usadas_na_conversao.add(str(ativ_id))
                _ids_resultado.append(str(ativ_id or ""))
            else:
                novo_id = criar_atividade(
                    user_id, "coleta_ads_google", titulo, detalhes, status="erro"
                )
                if novo_id:
                    _ids_resultado.append(str(novo_id))

        return _ids_resultado[0] if _ids_resultado else ""
    except Exception as exc:
        print(f"[GADS-V212] falha ao garantir atividade de incompletos: {exc!r}", flush=True)
        return ""

def preparar_refazer_gads_incompletos(user_id: str, atividade: dict) -> tuple:
    """Cria backup persistente e devolve as empresas da fila de incompletos."""
    atividade_id = atividade.get("id")
    detalhes = dict(atividade.get("detalhes") or {})
    ids_por_empresa = _ids_gads_incompletos_dos_detalhes(detalhes)
    if not atividade_id or not ids_por_empresa:
        return False, [], "A notificação não contém IDs pendentes."
    try:
        cache = _carregar_checkpoints_gads_r2(user_id)
        backup_por_empresa = {}
        for _empresa, _ids in ids_por_empresa.items():
            _ids_set = {str(x) for x in (_ids or [])}
            _ads = [dict(a) for a in ((cache.get(_empresa) or {}).get("data") or []) if str(a.get("id") or "") in _ids_set]
            if _ads:
                backup_por_empresa[_empresa] = _ads
        if not backup_por_empresa:
            return False, [], "Não encontrei os anúncios pendentes no cache atual."
        backup = {
            "plataforma": "Google Ads",
            "criado_em": _agora_iso(),
            "desfeito": False,
            "por_empresa": backup_por_empresa,
            "total": sum(len(v) for v in backup_por_empresa.values()),
        }
        detalhes["backup_desfazer"] = backup
        detalhes["aviso_backup"] = f"Backup de {backup['total']} anúncio(s) criado antes do reprocessamento."
        _supabase_resiliente(
            lambda: supabase.table("atividades").update({"detalhes": detalhes})
                    .eq("id", atividade_id).eq("user_id", user_id).execute(),
            operacao="backup_refazer_gads_incompletos", tentativas=5,
            backoff=(1, 2, 4, 8, 15),
        )
        _backups_desfazer_atividade[str(atividade_id)] = backup
        return True, list(backup_por_empresa.keys()), "Backup criado."
    except Exception as exc:
        return False, [], f"Não foi possível criar o backup: {exc}"

def refazer_migracao_midia(user_id: str, empresa: str, atividade_id: str, plataforma: str = "Meta Ads") -> bool:
    """Tenta a migração de novo pra uma empresa específica, usando os
    anúncios que já estão salvos no cache (não precisa recoletar).
    Reaproveita a MESMA atividade em vez de criar uma nova a cada
    tentativa — senão cada "Refazer" clicado acumula um registro de
    "erro" (a tentativa anterior, substituída) que não é uma falha de
    verdade, só polui a contagem do resumo.

    `plataforma` decide se a busca é em `ads_cache` (Meta) ou
    `gads_cache` (Google) — sem isso, clicar "Refazer" numa migração
    travada do Google Ads sempre devolvia False (a empresa nunca é
    encontrada em `ads_cache`, que é a coluna do Meta), como se a
    empresa tivesse sumido do banco."""
    try:
        coluna = "gads_cache" if plataforma == "Google Ads" else "ads_cache"
        res = supabase.table("ci_dados").select(coluna).eq("user_id", user_id).execute()
        cache_atual = (res.data[0].get(coluna) or {}) if res.data else {}
        entry = cache_atual.get(empresa)
        if not entry:
            return False

        if not _criar_backup_antes_de_refazer_migracao(
            user_id, atividade_id, empresa, plataforma, entry
        ):
            return False

        _resetar_falhas_midia_empresa(user_id, empresa)

        atualizar_atividade(atividade_id, "em_andamento", {"empresa": empresa, "plataforma": plataforma})
        threading.Thread(
            target=_migrar_midia_background,
            args=(user_id, empresa, entry, atividade_id, plataforma),
            daemon=True,
        ).start()
        return True
    except Exception:
        return False

def reparar_e_refazer_migracao(user_id: str, empresa: str, atividade_id: str, plataforma: str = "Google Ads") -> dict:
    """Repara uma migração que fechou como "sucesso" mas na verdade salvou
    lixo no R2 (ex.: página de erro/bloqueio do CDN disfarçada de imagem —
    bug do fallback sem validação de content-type em
    baixar_e_persistir_midia, já corrigido pra downloads NOVOS, mas que
    não conserta sozinho o que já foi salvo).

    Só clicar "Refazer" (refazer_migracao_midia) NÃO resolve esses casos:
    o campo images/videos do anúncio, no cache (ads_cache/gads_cache), já
    foi sobrescrito com a URL do R2 (o lixo). Como url_origem já começa
    com R2_PUBLIC_BASE, baixar_e_persistir_midia bate no early-return
    "já é uma mídia nossa no R2 — nada a fazer" e nunca tenta baixar de
    novo.

    Passos:
    1. Acha em `midias` os registros corrompidos desta empresa (mime_type
       que não é image/* nem video/* — o próprio content-type que a
       validação deveria ter barrado).
    2. Pra cada um, devolve a referência no cache do link do R2 (lixo) de
       volta pro url_origem original, salvo em `midias.url_origem` —
       usando a mesma RPC que a reconciliação já usa
       (substituir_url_no_ads_cache / substituir_url_no_gads_cache),
       então a escrita é atômica e não corre risco de sobrescrever
       migrações concorrentes de outra empresa.
    3. Só então apaga a linha corrompida de `midias` (e, melhor esforço,
       o objeto no R2) — nessa ordem, se o passo 2 falhar a linha
       corrompida continua lá (nada pior do que já estava) em vez de
       apagar e deixar o cache apontando pra um R2 que não existe mais.
    4. Reseta midias_falhas da empresa (mesmo que refazer_migracao_midia
       já faz) e dispara a migração de novo — agora com url_origem
       restaurado, o download de verdade acontece, com o código já
       corrigido.

    Devolve um resumo (quantos corrompidos achados, quantos reparados,
    falhas por item) pra log/depuração. Não levanta exceção pra fora —
    qualquer erro vira entrada em "falhas"."""
    falhas = []
    try:
        corrompidas = (
            supabase.table("midias")
            .select("id, url_origem, url_cdn, storage_key, tipo, mime_type")
            .eq("user_id", user_id)
            .eq("empresa", empresa)
            .execute()
        ).data or []
    except Exception as e:
        return {"total_corrompidas": 0, "reparados": 0, "falhas": [f"erro ao consultar midias: {e!r}"], "refazer_disparado": False}

    corrompidas = [
        m for m in corrompidas
        if not (m.get("mime_type") or "").startswith(("image/", "video/"))
    ]

    reparados = 0
    for m in corrompidas:
        try:
            supabase.rpc(_rpc_substituir_url_cache(plataforma), {
                "p_user_id": user_id,
                "p_url_antiga": m["url_cdn"],
                "p_url_nova": m["url_origem"],
            }).execute()

            supabase.table("midias").delete().eq("id", m["id"]).execute()

            if r2_client is not None and m.get("storage_key"):
                try:
                    r2_client.delete_object(Bucket=R2_BUCKET, Key=m["storage_key"])
                except Exception:
                    pass  # best-effort — não bloqueia o reparo por isso

            reparados += 1
        except Exception as e:
            falhas.append(f"id={m.get('id')} url_origem={m.get('url_origem')!r}: {e!r}")

    ok = refazer_migracao_midia(user_id, empresa, atividade_id, plataforma=plataforma)

    return {
        "total_corrompidas": len(corrompidas),
        "reparados": reparados,
        "falhas": falhas,
        "refazer_disparado": ok,
    }

def refazer_transcricao_video(user_id: str, empresa: str, atividade_id: str) -> bool:
    """Equivalente a refazer_migracao_midia, mas pra atividades
    `transcricao_video`: usado pelo botão "🔄 Refazer" no sino quando uma
    atividade de transcrição terminou como 'erro'. Reaproveita a MESMA
    atividade em vez de criar uma nova a cada tentativa, e devolve False
    (sem religar nada) se não sobrou nenhum vídeo pendente dessa empresa
    — o que evita ficar "girando" no botão sem fazer diferença nenhuma."""
    if not user_id or not empresa:
        return False
    total = _contar_transcricoes_pendentes(user_id, empresa)
    if not total:
        atualizar_atividade(atividade_id, "concluido", {"empresa": empresa, "transcritas": 0, "total": 0})
        return False
    with _lock_transcricao_pendente:
        if (user_id, empresa) in _transcricoes_empresa_ativas_agora:
            return True
        _transcricoes_empresa_ativas_agora.add((user_id, empresa))
    atualizar_atividade(atividade_id, "em_andamento", {"empresa": empresa, "transcritas": 0, "total": total})
    threading.Thread(
        target=_transcrever_pendentes_background,
        args=(user_id, empresa, atividade_id),
        daemon=True,
    ).start()
    return True

def refazer_ocr_gads(user_id: str, empresa: str, atividade_id: str) -> bool:
    """V143 — recoloca OCR em erro na fila global, sem furar a fila.

    Antes o botão Refazer iniciava ``_ocr_pendentes_background`` diretamente,
    fazendo a atividade virar ``em_andamento`` mesmo quando outro job pesado
    já estava rodando. Agora reutiliza o mesmo coordenador FIFO de OCR: nasce
    como ``na_fila`` e só muda para ``em_andamento`` quando o worker global
    realmente pegar a atividade.
    """
    if not user_id or not empresa:
        return False
    total = _contar_ocr_pendentes(user_id, empresa)
    if not total:
        atualizar_atividade(atividade_id, "concluido", {"empresa": empresa, "processadas": 0, "total": 0})
        return False

    try:
        with _lock_ocr_pendente:
            _ocr_empresas_ativas_agora.discard((user_id, empresa))
    except Exception:
        pass
    try:
        _job_release("ocr_gads", user_id, empresa)
    except Exception:
        pass

    iniciar_ocr_pendente_background(user_id, empresa, force=True)
    return True


def _refazer_coleta_redes_background(user_id: str, dados_atuais: list, alvos: list, atividade_id: str):
    """Roda em thread: recoleta só os perfis de `alvos` via RapidAPI e
    mescla o resultado de volta na lista completa (`dados_atuais`), sem
    mexer nos perfis que já tinham dado certo antes."""
    try:
        by_key = {(r.get("key") or r.get("nome")): r for r in dados_atuais}
        for alvo in alvos:
            r_col = coletar_rapidapi(alvo["instagram"])
            by_key[alvo.get("key") or alvo.get("nome")] = {**alvo, **(r_col or {"erro": "Sem resposta"})}

        resultados_lista = list(by_key.values())
        supabase.table("ci_dados").update({
            "metricas_redes": {
                "ultima_coleta": _agora_usuario().strftime("%d/%m/%Y %H:%M"),
                "dados": resultados_lista,
            },
        }).eq("user_id", user_id).execute()

        _nomes_ok = [r["nome"] for r in resultados_lista if not r.get("erro")]
        _com_erro = {r["nome"]: r["erro"] for r in resultados_lista if r.get("erro")}
        _total_posts = sum(len(r.get("posts", [])) for r in resultados_lista if not r.get("erro"))
        _status_final = "erro" if (_com_erro and not _nomes_ok) else "concluido"

        atualizar_atividade(atividade_id, _status_final, {
            "coletados": _nomes_ok,
            "com_erro": _com_erro,
            "total_posts": _total_posts,
        })
        iniciar_transcricao_reels_pendente_background(user_id)
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def refazer_coleta_redes(user_id: str, atividade_id: str, empresas_com_erro: list) -> bool:
    """Tenta recoletar, via RapidAPI, só os perfis que falharam numa coleta
    anterior de redes sociais — botão "Tentar novamente" que aparece no
    sino quando a atividade 'coleta_redes' termina com parte dos perfis
    em erro. Reaproveita a MESMA atividade (mesmo padrão de
    refazer_migracao_midia/refazer_transcricao_video) e não recoleta os
    perfis que já tinham dado certo antes."""
    if not user_id or not empresas_com_erro:
        return False
    try:
        cache_atual = _ler_blob_ci_dados_v291(
            user_id, "metricas_redes", padrao={}
        ) or {}
    except Exception:
        return False
    dados_atuais = cache_atual.get("dados") or []
    alvos = [r for r in dados_atuais if r.get("nome") in empresas_com_erro and r.get("instagram")]
    if not alvos:
        return False

    atualizar_atividade(atividade_id, "em_andamento", {"empresa": ", ".join(empresas_com_erro)})
    threading.Thread(
        target=_refazer_coleta_redes_background,
        args=(user_id, dados_atuais, alvos, atividade_id),
        daemon=True,
    ).start()
    return True


LIMIAR_MIGRACAO_TRAVADA_SEGUNDOS = 90

LIMIAR_HEARTBEAT_TRAVADA_SEGUNDOS = 50

def _migracao_travada(atividade: dict, limiar_segundos: int = LIMIAR_MIGRACAO_TRAVADA_SEGUNDOS) -> bool:
    """True quando uma atividade de migracao_midia já terminou uma
    passada com pendências (tem 'aviso' nos detalhes) e faz mais que
    `limiar_segundos` desde essa passada — ou seja, não tem nenhuma
    thread rodando nela agora, só está esperando.

    Quando a atividade tem 'ultimo_heartbeat_em' (heartbeat independente
    de item concluído — ver persistir_midias_de_ads), usamos ele em vez
    do heurístico antigo baseado em 'ultima_tentativa_em': esse campo só
    era regravado quando um item terminava, e com vídeo (ffmpeg + Whisper)
    um único item pode passar de 90s tranquilamente — os 3 workers presos
    em itens lentos ao mesmo tempo faziam isso achar (errado) que não
    tinha nenhuma thread ativa, mostrando 'Continuar' no meio de uma
    migração que seguia rodando normalmente.

    Antes de olhar qualquer timestamp, checa primeiro se ESTE MESMO
    processo já sabe, em memória, que tem uma thread processando essa
    empresa agora (ver _migracao_empresa_esta_ativa_agora) — isso evita
    o atraso de até ~20s entre a thread começar a trabalhar de verdade e
    o primeiro heartbeat ser escrito no banco, janela em que a tela
    dizia 'Parado' apesar de já ter uma migração rodando."""
    if atividade.get("tipo") != "migracao_midia" or atividade.get("status") != "em_andamento":
        return False
    d = atividade.get("detalhes") or {}
    empresa = d.get("empresa") or _extrair_empresa_do_titulo_migracao(atividade.get("titulo") or "")
    if empresa and _migracao_empresa_esta_ativa_agora(atividade.get("user_id"), empresa):
        return False
    if not d.get("aviso"):
        return False
    if d.get("ultimo_heartbeat_em"):
        return _segundos_desde(d["ultimo_heartbeat_em"]) >= LIMIAR_HEARTBEAT_TRAVADA_SEGUNDOS
    return _segundos_desde(d.get("ultima_tentativa_em", "")) >= limiar_segundos

_lock_retry_migracao = threading.Lock()

@st.cache_resource
def _get_usuarios_retry_migracao_ativo() -> set:
    return set()

_usuarios_retry_migracao_ativo = _get_usuarios_retry_migracao_ativo()

_lock_gads_onboarding_jobs = threading.Lock()

@st.cache_resource
def _get_gads_onboarding_jobs() -> dict:
    return {}

_gads_onboarding_jobs = _get_gads_onboarding_jobs()

def _gads_onboarding_job_set(job_id: str, **campos):
    with _lock_gads_onboarding_jobs:
        job = _gads_onboarding_jobs.setdefault(job_id, {})
        job.update(campos)

def _gads_onboarding_job_get(job_id: str) -> dict:
    with _lock_gads_onboarding_jobs:
        return dict(_gads_onboarding_jobs.get(job_id, {}))

def retentar_migracoes_travadas_automaticamente(user_id: str) -> bool:
    """Varre as migrações de mídia em aberto do usuário e refaz
    automaticamente TODAS as que estiverem travadas (ver
    _migracao_travada) num único lote sequencial — em vez de refazer
    só a mais antiga a cada ciclo do sino (12s) e depender de outro
    ciclo pra pegar a próxima.

    Antes, com 2+ empresas travadas ao mesmo tempo, elas ficavam se
    revezando uma por ciclo: cada rodada de retry cuidava de 1 empresa,
    e as outras ficavam ociosas esperando a vez, mesmo que a empresa em
    retry tivesse terminado rápido. Isso multiplicava o tempo total de
    fila sem nenhum ganho de segurança — o sistema já processa uma
    empresa de cada vez mesmo (ver _migrar_todas_empresas_sequencial,
    que existe justamente pra evitar Errno 11 de ffmpeg/Whisper
    concorrentes). Agrupar todas as travadas num só lote elimina esse
    tempo ocioso entre uma e outra sem aumentar a concorrência real:
    continua sendo 1 migração ativa por vez, só sem pausa artificial
    entre elas.

    Também evita N queries repetidas ao ads_cache (uma por empresa,
    como refazer_migracao_midia fazia sendo chamada individualmente) —
    aqui a busca é feita uma vez só pra montar o lote inteiro.

    Devolve True se disparou algum retry (útil pra decidir se vale a
    pena um st.rerun() logo em seguida)."""
    if not user_id:
        return False
    try:
        res = (
            supabase.table("atividades")
            .select("id, titulo, detalhes, status, criado_em")
            .eq("user_id", user_id)
            .eq("tipo", "migracao_midia")
            .eq("status", "em_andamento")
            .order("criado_em")
            .execute()
        )
    except Exception:
        return False

    candidatas = [a for a in (res.data or []) if _migracao_travada({**a, "user_id": user_id})]
    if not candidatas:
        return False

    try:
        cache_atual = _ler_blob_ci_dados_v291(
            user_id, "ads_cache", padrao={}
        ) or {}
        gcache_atual = _carregar_gads_cache_preferindo_r2_v249(user_id, "retry_migracao")
    except Exception:
        return False

    tarefas = []
    for alvo in candidatas:
        plataforma_alvo = (alvo.get("detalhes") or {}).get("plataforma") or "Meta Ads"
        cache_da_plataforma = gcache_atual if plataforma_alvo == "Google Ads" else cache_atual
        empresa = (alvo.get("detalhes") or {}).get("empresa")
        if not empresa:
            empresa = _extrair_empresa_do_titulo_migracao(alvo.get("titulo") or "")
        if not empresa:
            continue
        entry = cache_da_plataforma.get(empresa)
        if not entry:
            _detalhes_atuais = alvo.get("detalhes") or {}
            _tentativas_cache_ausente = _detalhes_atuais.get("tentativas_cache_ausente", 0) + 1
            print(
                f"[retry_migracao] empresa '{empresa}' (atividade {alvo['id']}, user {user_id}) "
                f"não encontrada em ads_cache — tentativa {_tentativas_cache_ausente}"
            )
            if _tentativas_cache_ausente >= 3:
                atualizar_atividade(alvo["id"], "erro", {
                    **_detalhes_atuais,
                    "empresa": empresa,
                    "motivo": (
                        f"Não encontramos mais os dados de '{empresa}' no cache pra continuar "
                        f"essa migração — a empresa pode ter sido removida ou renomeada. Faça uma "
                        f"nova coleta dela e clique em 'Refazer' pra tentar migrar de novo."
                    ),
                })
            else:
                atualizar_atividade(alvo["id"], "em_andamento", {
                    **_detalhes_atuais,
                    "empresa": empresa,
                    "tentativas_cache_ausente": _tentativas_cache_ausente,
                    "ultima_tentativa_em": _agora_iso(),
                })
            continue
        atualizar_atividade(alvo["id"], "em_andamento", {"empresa": empresa, "plataforma": plataforma_alvo})
        tarefas.append((empresa, entry, alvo["id"], plataforma_alvo))

    if not tarefas:
        return False

    with _lock_retry_migracao:
        if user_id in _usuarios_retry_migracao_ativo:
            return False
        _usuarios_retry_migracao_ativo.add(user_id)

    def _rodar_lote_e_liberar():
        try:
            _migrar_todas_empresas_sequencial(user_id, tarefas)
        finally:
            with _lock_retry_migracao:
                _usuarios_retry_migracao_ativo.discard(user_id)

    threading.Thread(target=_rodar_lote_e_liberar, daemon=True).start()
    return True

LIMIAR_TRANSCRICAO_ERRO_COOLDOWN_SEGUNDOS = 300  # 5 min entre tentativas automáticas

def retentar_transcricoes_com_erro_automaticamente(user_id: str) -> bool:
    """Varre as atividades transcricao_video em 'erro' do usuário e
    refaz automaticamente as que já passaram do cooldown desde a última
    falha (ver LIMIAR_TRANSCRICAO_ERRO_COOLDOWN_SEGUNDOS). Devolve True
    se disparou algum retry."""
    if not user_id:
        return False
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "transcricao_video")
            .eq("status", "erro")
            .execute()
        )
    except Exception:
        return False

    disparou = False
    for a in (res.data or []):
        d = a.get("detalhes") or {}
        empresa = d.get("empresa")
        if not empresa:
            continue
        if _segundos_desde(d.get("falhou_em", "")) < LIMIAR_TRANSCRICAO_ERRO_COOLDOWN_SEGUNDOS:
            continue
        if refazer_transcricao_video(user_id, empresa, a["id"]):
            disparou = True
    return disparou


