def _suporte_resumo_cc_youtube_v153(user_id: str) -> dict:
    """
    Conta vídeos únicos do YouTube presentes no Google Ads diretamente no
    gads_cache. Não usa `midias`, porque links YouTube são externos e o CC
    fica salvo no próprio anúncio (`video_cc_raw`).
    """
    _cache = _carregar_gads_cache_cc_v153(user_id)
    _videos = {}
    _por_empresa = {}

    for _empresa, _entry in (_cache or {}).items():
        _empresa_map = {}
        for _ad in (_entry or {}).get("data", []) or []:
            _cc = str(_ad.get("video_cc_raw") or "").strip()
            for _url in (_ad.get("videos") or []):
                _vid = _youtube_video_id_v150(_url)
                if not _vid:
                    continue
                _prev = _videos.get(_vid, False)
                _videos[_vid] = bool(_prev or _cc)
                _prev_emp = _empresa_map.get(_vid, False)
                _empresa_map[_vid] = bool(_prev_emp or _cc)
        if _empresa_map:
            _por_empresa[_empresa] = {
                "total": len(_empresa_map),
                "com_cc": sum(1 for _ok in _empresa_map.values() if _ok),
                "sem_cc": sum(1 for _ok in _empresa_map.values() if not _ok),
            }

    _total = len(_videos)
    _com = sum(1 for _ok in _videos.values() if _ok)
    return {
        "total": _total,
        "com_cc": _com,
        "sem_cc": _total - _com,
        "por_empresa": _por_empresa,
    }


def _suporte_inventario_midias(user_id: str) -> list:
    """Monta uma visão administrativa única das mídias salvas e pendentes.

    A fonte principal é o cache dos anúncios (`ads_cache` + `gads_cache`),
    porque é nele que conseguimos enxergar também as mídias que AINDA estão
    apenas como link externo e nunca chegaram a gerar uma linha em `midias`.
    A tabela `midias` entra como complemento para indicar transcrição/OCR e
    também para incluir arquivos permanentes órfãos do cache atual.
    """
    if not user_id:
        return []
    try:
        _ci = (
            supabase.table("ci_dados")
            .select("ads_cache,gads_cache")
            .eq("user_id", user_id)
            .execute()
        )
        _row = _ci.data[0] if _ci.data else {}
        _ads_cache = _row.get("ads_cache") or {}
        _gads_cache = _row.get("gads_cache") or {}
    except Exception:
        _ads_cache, _gads_cache = {}, {}

    try:
        _mid_res = (
            supabase.table("midias")
            .select("id,empresa,ad_id,tipo,url_origem,url_cdn,storage_key,mime_type,transcricao,ocr_texto,ocr_estruturado,criado_em")
            .eq("user_id", user_id)
            .limit(10000)
            .execute()
        )
        _mid_rows = _mid_res.data or []
    except Exception:
        _mid_rows = []

    _por_cdn = {}
    _por_origem = {}
    for _m in _mid_rows:
        if _m.get("url_cdn"):
            _por_cdn[_m["url_cdn"]] = _m
        if _m.get("url_origem"):
            _por_origem[_m["url_origem"]] = _m

    _itens = []
    _vistos = set()

    _gads_formato_por_ad = {}
    for _empresa_fmt, _entry_fmt in (_gads_cache or {}).items():
        for _ad_fmt in (_entry_fmt.get("data") or []):
            _aid_fmt = str(_ad_fmt.get("id") or "")
            _fmt = (_ad_fmt.get("formato") or "").strip()
            if _fmt == "Imagem":
                _fmt = "Gráfico"
            if _aid_fmt:
                _gads_formato_por_ad[(_empresa_fmt or "Sem empresa", _aid_fmt)] = _fmt

    def _add_cache(_cache, _plataforma):
        for _empresa, _entry in (_cache or {}).items():
            for _ad in (_entry.get("data") or []):
                _ad_id = str(_ad.get("id") or "")
                for _tipo, _campo in (("imagem", "images"), ("video", "videos")):
                    for _idx, _url in enumerate(_ad.get(_campo) or []):
                        if not _url:
                            continue
                        _chave = (_plataforma, _empresa, _ad_id, _tipo, _url)
                        if _chave in _vistos:
                            continue
                        _vistos.add(_chave)
                        _salva = bool(R2_PUBLIC_BASE and _url.startswith(R2_PUBLIC_BASE))
                        _m = _por_cdn.get(_url) or _por_origem.get(_url) or {}
                        _trans = _m.get("transcricao")
                        _ocr = _m.get("ocr_texto")
                        _empresa_norm = _empresa or "Sem empresa"
                        _formato_ad = ""
                        if _plataforma == "Google Ads":
                            _formato_ad = _gads_formato_por_ad.get((_empresa_norm, _ad_id), "")
                        _ocr_elegivel = (
                            _tipo == "imagem"
                            and _plataforma == "Google Ads"
                            and _formato_ad != "Vídeo"
                        )
                        if _tipo == "video":
                            _motivo_ocr = "Vídeo — processamento por transcrição; OCR não se aplica"
                        elif _plataforma != "Google Ads":
                            _motivo_ocr = "Imagem fora do Google Ads — OCR não se aplica"
                        elif _formato_ad == "Vídeo":
                            _motivo_ocr = "Capa/thumbnail de anúncio em vídeo — OCR não se aplica"
                        elif bool((_ocr or "").strip()):
                            _motivo_ocr = "OCR concluído"
                        else:
                            _motivo_ocr = "OCR pendente ou não executado"
                        _eh_youtube = bool(_tipo == "video" and _e_url_youtube(_url))
                        _itens.append({
                            "empresa": _empresa_norm,
                            "plataforma": _plataforma,
                            "ad_id": _ad_id,
                            "formato_anuncio": _formato_ad,
                            "tipo": _tipo,
                            "indice": _idx,
                            "url": _url,
                            "eh_youtube": _eh_youtube,
                            "so_link_pendente": bool((not _salva) and (not _eh_youtube)),
                            "salva": _salva,
                            "midia_id": _m.get("id"),
                            "url_origem": _m.get("url_origem") or (None if _salva else _url),
                            "url_cdn": _m.get("url_cdn") or (_url if _salva else None),
                            "transcricao": _trans,
                            "tem_transcricao": bool((_trans or "").strip()),
                            "ocr_texto": _ocr,
                            "tem_ocr": bool((_ocr or "").strip()),
                            "ocr_elegivel": _ocr_elegivel,
                            "motivo_ocr": _motivo_ocr,
                            "origem_cache": True,
                        })

    _add_cache(_ads_cache, "Meta Ads")
    _add_cache(_gads_cache, "Google Ads")

    _urls_vistas = {i["url"] for i in _itens}
    for _m in _mid_rows:
        _url = _m.get("url_cdn")
        if not _url or _url in _urls_vistas:
            continue
        _orig = _m.get("url_origem") or ""
        _tipo = _m.get("tipo") or ("video" if ("video" in (_m.get("mime_type") or "")) else "imagem")
        _trans = _m.get("transcricao")
        _ocr = _m.get("ocr_texto")
        _empresa_norm = _m.get("empresa") or "Sem empresa"
        _ad_id_norm = str(_m.get("ad_id") or "")
        _ad_google_no_cache = (_empresa_norm, _ad_id_norm) in _gads_formato_por_ad
        _id_google_ads = bool(re.match(r"(?i)^CR\d+$", _ad_id_norm.strip()))
        if _ad_google_no_cache or _id_google_ads:
            _plat = "Google Ads"
        else:
            _plat = _plataforma_da_url(_orig)
        _formato_ad = _gads_formato_por_ad.get((_empresa_norm, _ad_id_norm), "") if _plat == "Google Ads" else ""
        _ocr_elegivel = (
            _tipo == "imagem"
            and _plat == "Google Ads"
            and _formato_ad != "Vídeo"
        )
        if _tipo == "video":
            _motivo_ocr = "Vídeo — processamento por transcrição; OCR não se aplica"
        elif _plat != "Google Ads":
            _motivo_ocr = "Imagem fora do Google Ads — OCR não se aplica"
        elif _formato_ad == "Vídeo":
            _motivo_ocr = "Capa/thumbnail de anúncio em vídeo — OCR não se aplica"
        elif bool((_ocr or "").strip()):
            _motivo_ocr = "OCR concluído"
        else:
            _motivo_ocr = "OCR pendente ou não executado"
        _eh_youtube = bool(_tipo == "video" and _e_url_youtube(_orig or _url))
        _itens.append({
            "empresa": _empresa_norm,
            "plataforma": _plat,
            "ad_id": _ad_id_norm,
            "formato_anuncio": _formato_ad,
            "tipo": _tipo,
            "indice": 0,
            "url": _url,
            "eh_youtube": _eh_youtube,
            "so_link_pendente": False,
            "salva": True,
            "midia_id": _m.get("id"),
            "url_origem": _orig or None,
            "url_cdn": _url,
            "transcricao": _trans,
            "tem_transcricao": bool((_trans or "").strip()),
            "ocr_texto": _ocr,
            "tem_ocr": bool((_ocr or "").strip()),
            "ocr_elegivel": _ocr_elegivel,
            "motivo_ocr": _motivo_ocr,
            "origem_cache": False,
        })
    return _itens


def _suporte_resumo_midias_por_empresa(itens: list) -> list:
    """Resumo de suporte separando mídia pendente de link YouTube.

    V163:
    - `Só link` = mídia externa ainda não persistida (exclui YouTube);
    - `YouTube` = links de vídeo hospedados no YouTube, que permanecem externos
      por desenho e só desaparecem se o anúncio/link for removido;
    - transcrição normal contabiliza apenas vídeos não-YouTube; YouTube usa CC.
    """
    _grupos = {}
    for _i in itens or []:
        _g = _grupos.setdefault(_i["empresa"], {
            "Empresa": _i["empresa"],
            "Mídias": 0,
            "Salvas": 0,
            "Só link": 0,
            "YouTube": 0,
            "Vídeos": 0,
            "Com transcrição": 0,
            "Sem transcrição": 0,
            "Imagens c/ OCR": 0,
            "Imagens s/ OCR": 0,
        })
        _g["Mídias"] += 1
        _eh_youtube = bool(_i.get("eh_youtube"))
        if _eh_youtube:
            _g["YouTube"] += 1
        elif _i.get("salva"):
            _g["Salvas"] += 1
        elif _i.get("so_link_pendente", not _i.get("salva")):
            _g["Só link"] += 1

        if _i.get("tipo") == "video" and not _eh_youtube:
            _g["Vídeos"] += 1
            _g["Com transcrição" if _i.get("tem_transcricao") else "Sem transcrição"] += 1
        if _i.get("ocr_elegivel"):
            _g["Imagens c/ OCR" if _i.get("tem_ocr") else "Imagens s/ OCR"] += 1
    return sorted(_grupos.values(), key=lambda x: x["Empresa"].lower())


def _suporte_refazer_midia_especifica(user_id: str, item: dict):
    """Refaz apenas a etapa necessária da mídia escolhida no painel."""
    if not item:
        return False, "Mídia não encontrada."
    _empresa = item.get("empresa") or ""
    _tipo = item.get("tipo") or ""
    _plataforma = item.get("plataforma") or "Meta Ads"

    if not item.get("salva"):
        _url_antiga = item.get("url") or item.get("url_origem") or ""
        if not _url_antiga:
            return False, "Link original vazio."
        _url_nova = baixar_e_persistir_midia(
            _url_antiga, user_id, _empresa, _tipo,
            item.get("ad_id") or None,
        )
        if not _url_nova or _url_nova == _url_antiga:
            return False, "A mídia continuou apenas como link. Veja as notificações/logs para o motivo."
        try:
            supabase.rpc(_rpc_substituir_url_cache(_plataforma), {
                "p_user_id": user_id,
                "p_url_antiga": _url_antiga,
                "p_url_nova": _url_nova,
            }).execute()
        except Exception as _e:
            return False, f"Arquivo salvo, mas não consegui atualizar o cache: {_e}"
        if _tipo == "video":
            iniciar_transcricao_pendente_background(user_id, _empresa)
        elif _tipo == "imagem" and _plataforma == "Google Ads":
            iniciar_ocr_pendente_background(user_id, _empresa)
        return True, "Mídia salva novamente e enviada para o processamento correspondente."

    try:
        if _tipo == "video":
            _q = supabase.table("midias").update({"transcricao": None}).eq("user_id", user_id)
            if item.get("midia_id"):
                _q = _q.eq("id", item["midia_id"])
            else:
                _q = _q.eq("url_cdn", item.get("url_cdn") or item.get("url"))
            _q.execute()
            iniciar_transcricao_pendente_background(user_id, _empresa)
            return True, "Transcrição desta mídia enviada para refazer."

        if _tipo == "imagem" and _plataforma == "Google Ads":
            _q = supabase.table("midias").update({
                "ocr_texto": None,
                "ocr_estruturado": None,
            }).eq("user_id", user_id)
            if item.get("midia_id"):
                _q = _q.eq("id", item["midia_id"])
            else:
                _q = _q.eq("url_cdn", item.get("url_cdn") or item.get("url"))
            _q.execute()
            iniciar_ocr_pendente_background(user_id, _empresa)
            return True, "OCR desta imagem enviado para refazer."

        return False, "Essa mídia não tem uma etapa individual de OCR/transcrição para refazer."
    except Exception as _e:
        return False, f"Não foi possível refazer esta mídia: {_e}"


def _rapidapi_get_com_retry(url: str, headers: dict, tentativas: int = 3, timeout: int = 20):
    """GET com retry + backoff pra aguentar instabilidade da API do
    RapidAPI (timeouts pontuais são comuns em horários de pico).
    Levanta a última exceção se todas as tentativas falharem."""
    import time
    ultimo_erro = None
    for i in range(tentativas):
        try:
            return _http_get(url, headers=headers, timeout=timeout)
        except requests.exceptions.RequestException as e:
            ultimo_erro = e
            if i < tentativas - 1:
                time.sleep(1.5 * (i + 1))  # backoff: 1.5s, 3s
    raise ultimo_erro

def _coletar_rapidapi_sem_cache(handle: str) -> dict:
    handle_limpo = handle.lstrip("@").strip()
    if not handle_limpo:
        return {"erro": "Handle vazio"}
    try:
        rapidapi_key = st.secrets.get("RAPIDAPI_KEY", "")
        if not rapidapi_key:
            return {"erro": "RAPIDAPI_KEY não configurada"}

        headers = {
            "x-rapidapi-key": rapidapi_key,
            "x-rapidapi-host": "instagram-looter2.p.rapidapi.com",
        }

        try:
            r = _rapidapi_get_com_retry(
                f"https://instagram-looter2.p.rapidapi.com/profile2?username={handle_limpo}",
                headers=headers,
            )
        except requests.exceptions.Timeout:
            return {"erro": "A API do Instagram demorou demais pra responder (timeout). Tenta de novo em instantes."}
        except requests.exceptions.RequestException as e:
            return {"erro": f"Falha ao conectar na API do Instagram: {e}"}
        data = r.json()
        user_data = data
        if isinstance(data, dict):
            if "data" in data:   user_data = data["data"]
            elif "user" in data: user_data = data["user"]

        if not user_data or user_data.get("status") is False or "message" in user_data or "errorMessage" in user_data:
            _msg_erro_rapidapi = (
                user_data.get("errorMessage")
                or user_data.get("message")
                or "Perfil não encontrado"
            ) if isinstance(user_data, dict) else "Perfil não encontrado"
            return {"erro": _msg_erro_rapidapi}

        seg         = int(user_data.get("follower_count") or user_data.get("edge_followed_by", {}).get("count") or 0)
        total_posts = int(user_data.get("media_count") or user_data.get("edge_owner_to_timeline_media", {}).get("count") or 0)
        pk          = str(user_data.get("pk") or user_data.get("id") or "").strip()

        posts_data = []
        if pk:
            for endpoint in [
                f"https://instagram-looter2.p.rapidapi.com/user-feeds?id={pk}&count=12&allow_restricted_media=false",
                f"https://instagram-looter2.p.rapidapi.com/user-medias?id={pk}&count=12",
            ]:
                try:
                    rp    = _rapidapi_get_com_retry(endpoint, headers=headers)
                    pr    = rp.json()
                    items = pr if isinstance(pr, list) else pr.get("items", [])
                    if items:
                        for p in items[:12]:
                            likes    = int(p.get("like_count") or 0)
                            comments = int(p.get("comment_count") or 0)

                            thumb = ""
                            thumb_hd = ""
                            if p.get("image_versions2"):
                                cands = p["image_versions2"].get("candidates", [])
                                if cands:
                                    cands_sorted = sorted(cands, key=lambda c: c.get("width", 0), reverse=True)
                                    thumb_hd = cands_sorted[0].get("url", "")
                                    thumb = cands_sorted[-1].get("url", "")
                                    if len(cands_sorted) == 1:
                                        thumb = thumb_hd
                                else:
                                    thumb_hd = ""
                                    thumb = ""

                            if not thumb_hd:
                                thumb_hd = (
                                    p.get("display_url")
                                    or p.get("thumbnail_src")
                                    or p.get("image_url")
                                    or ""
                                )

                            if p.get("display_resources"):
                                resources = sorted(
                                    p["display_resources"],
                                    key=lambda r: r.get("config_width", 0),
                                    reverse=True
                                )
                                if resources:
                                    thumb_hd = resources[0].get("src", "") or thumb_hd

                            if not thumb_hd:
                                thumb_hd = thumb

                            if not thumb:
                                thumb = thumb_hd

                            if p.get("thumbnail_url") and not thumb:
                                thumb = p["thumbnail_url"]
                                if not thumb_hd:
                                    thumb_hd = thumb

                            caption  = ""
                            if p.get("caption"):
                                caption = (
                                    p["caption"].get("text", "")
                                    if isinstance(p["caption"], dict)
                                    else str(p["caption"])
                                )[:500]
                            taken_at = p.get("taken_at", 0)
                            date_str = ""
                            if taken_at:
                                try:
                                    date_str = datetime.datetime.fromtimestamp(taken_at).strftime("%d/%m/%Y")
                                except Exception:
                                    pass
                            shortcode = p.get("code") or p.get("shortcode") or ""
                            post_url  = f"https://www.instagram.com/p/{shortcode}/" if shortcode else ""

                            media_type = p.get("media_type", 1)
                            is_reel = media_type == 2

                            video_url = ""
                            if is_reel:
                                video_url = (
                                    p.get("video_url")
                                    or (p.get("video_versions") or [{}])[0].get("url", "")
                                    or ""
                                )

                            carousel_imgs = []
                            carousel_imgs_hd = []

                            if media_type == 8:
                                for slide in (p.get("carousel_media") or []):
                                    cands = slide.get("image_versions2", {}).get("candidates", [])
                                    url_hd     = cands[0].get("url", "") if cands else ""
                                    url_thumb  = cands[-1].get("url", "") if cands else url_hd
                                    url_display = slide.get("display_uri", "")

                                    escolhida_hd    = url_hd or url_display
                                    escolhida_thumb = url_thumb or url_display or url_hd

                                    if escolhida_hd:
                                        carousel_imgs_hd.append(escolhida_hd)
                                    if escolhida_thumb:
                                        carousel_imgs.append(escolhida_thumb)

                                if not carousel_imgs and thumb:
                                    carousel_imgs = [thumb]
                                if not carousel_imgs_hd and thumb_hd:
                                    carousel_imgs_hd = [thumb_hd]

                            posts_data.append({
                                "likes":          likes,
                                "comments":       comments,
                                "thumb":          thumb,
                                "thumb_hd":       thumb_hd,
                                "display_url":    p.get("display_url") or p.get("thumbnail_src") or p.get("image_url") or thumb_hd,
                                "caption":        caption,
                                "date":           date_str,
                                "is_video":       is_reel,
                                "media_type":     media_type,
                                "video_url":      video_url,
                                "post_url":       post_url,
                                "shortcode":      shortcode,
                                "carousel_imgs":  carousel_imgs,
                                "carousel_imgs_hd": carousel_imgs_hd,
                                "_raw": {
                                    k: v for k, v in p.items()
                                    if k not in ("carousel_media", "video_versions", "image_versions2")
                                },
                                "_raw_image_versions2": {
                                    "candidates": [
                                        {"width": c.get("width"), "height": c.get("height"), "url": c.get("url", "")[:80] + "..."}
                                        for c in (p.get("image_versions2") or {}).get("candidates", [])
                                    ]
                                },
                                "_raw_display_resources": p.get("display_resources", []),
                            })
                        break
                except Exception:
                    continue

        if total_posts == 0 and posts_data:
            total_posts = len(posts_data)

        if seg == 0 and total_posts == 0 and not posts_data:
            return {"erro": "A API não retornou dados para este perfil (perfil privado, incorreto ou instabilidade momentânea). Tente coletar novamente."}

        if posts_data:
            eng_medio = sum(p["likes"] + p["comments"] for p in posts_data) / len(posts_data)
            eng_pct   = round(eng_medio / seg * 100, 2) if seg > 0 else 0.0
        else:
            eng_pct   = 3.0 if seg <= 10_000 else (2.0 if seg <= 50_000 else (1.5 if seg <= 100_000 else 1.0))
            eng_medio = round(seg * eng_pct / 100, 1)

        _profile_pic_raw = (
            user_data.get("profile_pic_url_hd")
            or user_data.get("profile_pic_url")
            or user_data.get("hd_profile_pic_url_info", {}).get("url", "")
            or ""
        )

        if not _profile_pic_raw and posts_data:
            try:
                raw = posts_data[0].get("_raw", {})
                _profile_pic_raw = (
                    raw.get("user", {}).get("profile_pic_url_hd", "")
                    or raw.get("user", {}).get("profile_pic_url", "")
                    or raw.get("caption", {}).get("user", {}).get("profile_pic_url_hd", "")
                    or raw.get("caption", {}).get("user", {}).get("profile_pic_url", "")
                    or ""
                )
            except Exception:
                pass

        profile_pic = _profile_pic_raw

        if profile_pic:
            try:
                import requests as _req
                import base64 as _b64
                _r = _req.get(profile_pic, timeout=8, headers={"User-Agent": "Mozilla/5.0"})
                if _r.status_code == 200:
                    _mime = _r.headers.get("content-type", "image/jpeg").split(";")[0]
                    profile_pic = f"data:{_mime};base64,{_b64.b64encode(_r.content).decode()}"
            except Exception:
                pass

        _bio_links = user_data.get("bio_links") or []
        _all_urls = [
            link.get("url", "") for link in _bio_links if link.get("url", "")
        ]
        if not _all_urls and user_data.get("external_url"):
            _all_urls = [user_data["external_url"]]
        _external_url = " | ".join(_all_urls)

        return {
            "handle":       "@" + handle_limpo,
            "nome_exibido": user_data.get("full_name") or user_data.get("username", handle_limpo),
            "seguidores":   seg,
            "seguindo":     int(user_data.get("following_count") or 0),
            "total_posts":  total_posts,
            "bio":          (user_data.get("biography") or ""),
            "external_url": _external_url,
            "is_verified":  user_data.get("is_verified", False),
            "eng_medio":    round(eng_medio, 1),
            "eng_pct":      eng_pct,
            "posts":        posts_data,
            "fonte":        "rapidapi",
            "erro":         None,
            "profile_pic":  profile_pic,
        }
    except Exception as e:
        return {"erro": str(e)}

_RAPIDAPI_CACHE_TTL = 1800  # 30 min

def coletar_rapidapi(handle: str) -> dict:
    import time
    cache = st.session_state.setdefault("_cache_rapidapi", {})
    agora = time.time()
    entrada = cache.get(handle)
    if entrada and (agora - entrada["ts"]) < _RAPIDAPI_CACHE_TTL:
        return entrada["dados"]

    resultado = _coletar_rapidapi_sem_cache(handle)
    if not resultado.get("erro"):
        cache[handle] = {"ts": agora, "dados": resultado}
    return resultado


